  'Saved {name}: the annual return tables from the months so far, for your CA to complete and file.': '{name} ಉಳಿಸಲಾಗಿದೆ: ಇಲ್ಲಿಯವರೆಗಿನ ತಿಂಗಳುಗಳಿಂದ ವಾರ್ಷಿಕ ರಿಟರ್ನ್ ಟೇಬಲ್‌ಗಳು, ನಿಮ್ಮ CA ಪೂರ್ತಿ ಮಾಡಿ ಫೈಲ್ ಮಾಡಲು.',
  'The filing pack could not be prepared.': 'ಫೈಲಿಂಗ್ ಪ್ಯಾಕ್ ತಯಾರಿಸಲು ಆಗಲಿಲ್ಲ.',
  'Saved {name}: GSTR-1, GSTR-3B, the amount to pay and the trial balance in one file for your CA to file on GSTN.': '{name} ಉಳಿಸಲಾಗಿದೆ: GSTR-1, GSTR-3B, ಕಟ್ಟಬೇಕಾದ ಮೊತ್ತ ಮತ್ತು ಟ್ರಯಲ್ ಬ್ಯಾಲೆನ್ಸ್ ಒಂದೇ ಫೈಲ್‌ನಲ್ಲಿ, ನಿಮ್ಮ CA GSTN ನಲ್ಲಿ ಫೈಲ್ ಮಾಡಲು.',
  'No Form 16A draft for {quarter}: nothing was deducted in it.': '{quarter} ಗೆ Form 16A ಡ್ರಾಫ್ಟ್ ಇಲ್ಲ: ಅದರಲ್ಲಿ ಏನೂ ಕಡಿತವಾಗಿಲ್ಲ.',
  'Saved {name} with 1 deductee. The certificates themselves are generated on TRACES once the statement is processed.': '{name} 1 ಡಿಡಕ್ಟೀ ಜೊತೆ ಉಳಿಸಲಾಗಿದೆ. ಸ್ಟೇಟ್‌ಮೆಂಟ್ ಪ್ರೊಸೆಸ್ ಆದ ನಂತರ ನಿಜವಾದ ಸರ್ಟಿಫಿಕೇಟ್‌ಗಳು TRACES ನಲ್ಲಿ ತಯಾರಾಗುತ್ತವೆ.',
  'Saved {name} with {n} deductees. The certificates themselves are generated on TRACES once the statement is processed.': '{name} {n} ಡಿಡಕ್ಟೀಗಳ ಜೊತೆ ಉಳಿಸಲಾಗಿದೆ. ಸ್ಟೇಟ್‌ಮೆಂಟ್ ಪ್ರೊಸೆಸ್ ಆದ ನಂತರ ನಿಜವಾದ ಸರ್ಟಿಫಿಕೇಟ್‌ಗಳು TRACES ನಲ್ಲಿ ತಯಾರಾಗುತ್ತವೆ.',
  'The file could not be prepared.': 'ಫೈಲ್ ತಯಾರಿಸಲು ಆಗಲಿಲ್ಲ.',
  'Saved {name}. Upload it in the GST offline tool or send it to your CA.': '{name} ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು GST ಆಫ್‌ಲೈನ್ ಟೂಲ್‌ನಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಅಥವಾ ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'The trial balance could not be prepared.': 'ಟ್ರಯಲ್ ಬ್ಯಾಲೆನ್ಸ್ ತಯಾರಿಸಲು ಆಗಲಿಲ್ಲ.',
  'The entries could not be prepared.': 'ಎಂಟ್ರಿಗಳನ್ನು ತಯಾರಿಸಲು ಆಗಲಿಲ್ಲ.',
  'Saved {name} with 1 account. Send it to your CA.': '{name} 1 ಖಾತೆಯೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Saved {name} with 1 account (it does not tie; ask your CA to look). Send it to your CA.': '{name} 1 ಖಾತೆಯೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ (ಮೊತ್ತ ಹೊಂದುತ್ತಿಲ್ಲ; ನಿಮ್ಮ CA ಗೆ ನೋಡಲು ಹೇಳಿ). ಇದನ್ನು ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Saved {name} with {n} accounts. Send it to your CA.': '{name} {n} ಖಾತೆಗಳೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Saved {name} with {n} accounts (it does not tie; ask your CA to look). Send it to your CA.': '{name} {n} ಖಾತೆಗಳೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ (ಮೊತ್ತ ಹೊಂದುತ್ತಿಲ್ಲ; ನಿಮ್ಮ CA ಗೆ ನೋಡಲು ಹೇಳಿ). ಇದನ್ನು ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Saved {name} with 1 voucher. Import it in Tally (Import Data) or send it to your CA.': '{name} 1 ವೋಚರ್ ಜೊತೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು Tally ಯಲ್ಲಿ ಇಂಪೋರ್ಟ್ ಮಾಡಿ (Import Data) ಅಥವಾ ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Saved {name} with {n} vouchers. Import it in Tally (Import Data) or send it to your CA.': '{name} {n} ವೋಚರ್‌ಗಳ ಜೊತೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು Tally ಯಲ್ಲಿ ಇಂಪೋರ್ಟ್ ಮಾಡಿ (Import Data) ಅಥವಾ ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Saved {name} with 1 entry. Send it to your CA.': '{name} 1 ಎಂಟ್ರಿಯೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Saved {name} with {n} entries. Send it to your CA.': '{name} {n} ಎಂಟ್ರಿಗಳೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
