  'If paid today, {n} days late: interest {interest} and late fee {fee}, {total} in all.': 'ಇಂದು ಕಟ್ಟಿದರೆ {n} ದಿನ ತಡ: ಬಡ್ಡಿ {interest} ಮತ್ತು ಲೇಟ್ ಫೀ {fee}, ಒಟ್ಟು {total}.',
