  'GSTR-1 FILE FOR {month}': '{month} ರ GSTR-1 ಫೈಲ್',
  'No sales to report for this month.': 'ಈ ತಿಂಗಳು ತೋರಿಸಲು ಯಾವ ಮಾರಾಟವೂ ಇಲ್ಲ.',
  '{b2b} to registered buyers · {b2cl} large to unregistered · {n} summary row': '{b2b} ರಿಜಿಸ್ಟರ್ಡ್ ಖರೀದಿದಾರರಿಗೆ · {b2cl} ರಿಜಿಸ್ಟರ್ ಆಗದವರಿಗೆ ದೊಡ್ಡ ಬಿಲ್ · {n} ಸಾರಾಂಶ ಸಾಲು',
  '{b2b} to registered buyers · {b2cl} large to unregistered · {n} summary rows': '{b2b} ರಿಜಿಸ್ಟರ್ಡ್ ಖರೀದಿದಾರರಿಗೆ · {b2cl} ರಿಜಿಸ್ಟರ್ ಆಗದವರಿಗೆ ದೊಡ್ಡ ಬಿಲ್ · {n} ಸಾರಾಂಶ ಸಾಲುಗಳು',
  'Preparing…': 'ತಯಾರಾಗುತ್ತಿದೆ…',
  'Save file for the GST portal': 'GST ಪೋರ್ಟಲ್‌ಗಾಗಿ ಫೈಲ್ ಉಳಿಸಿ',
  'File GSTR-1 on the GST portal': 'GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ GSTR-1 ಫೈಲ್ ಮಾಡಿ',
  'File GSTR-3B on the GST portal': 'GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ GSTR-3B ಫೈಲ್ ಮಾಡಿ',
  'MyCA does not upload or file this. You or your CA do that on the GST portal.': 'MyCA ಇದನ್ನು ಅಪ್‌ಲೋಡ್ ಅಥವಾ ಫೈಲ್ ಮಾಡುವುದಿಲ್ಲ. ಅದನ್ನು ನೀವು ಅಥವಾ ನಿಮ್ಮ CA GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಮಾಡುತ್ತೀರಿ.',
  'Save the file to upload it yourself, or file GSTR-1 and GSTR-3B on the GST portal from here with the portal OTP.': 'ನೀವೇ ಅಪ್‌ಲೋಡ್ ಮಾಡಲು ಫೈಲ್ ಉಳಿಸಿ, ಅಥವಾ ಪೋರ್ಟಲ್ OTP ಬಳಸಿ ಇಲ್ಲಿಂದಲೇ GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ GSTR-1 ಮತ್ತು GSTR-3B ಫೈಲ್ ಮಾಡಿ.',
  'Choose the return that was filed.': 'ಫೈಲ್ ಆದ ರಿಟರ್ನ್ ಆಯ್ಕೆಮಾಡಿ.',
  'Enter the acknowledgement number (ARN) as printed: 10 to 20 letters and digits.': 'ಅಕ್ನಾಲೆಜ್‌ಮೆಂಟ್ ನಂಬರ್ (ARN) ಮುದ್ರಿತವಾದಂತೆ ಹಾಕಿ: 10 ರಿಂದ 20 ಅಕ್ಷರ ಮತ್ತು ಅಂಕಿ.',
  '{form} for {month} filed on {date}, ARN {arn}': '{month} ರ {form} {date} ರಂದು ಫೈಲ್ ಆಗಿದೆ, ARN {arn}',
  'For a return already filed on the GST portal or by your CA. MyCA files nothing; it keeps the acknowledgement and stops showing the return as due.': 'GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಥವಾ ನಿಮ್ಮ CA ಈಗಾಗಲೇ ಫೈಲ್ ಮಾಡಿದ ರಿಟರ್ನ್‌ಗಾಗಿ. MyCA ಏನನ್ನೂ ಫೈಲ್ ಮಾಡುವುದಿಲ್ಲ; ಅದು ಅಕ್ನಾಲೆಜ್‌ಮೆಂಟ್ ಇಟ್ಟುಕೊಂಡು ಆ ರಿಟರ್ನ್ ಬಾಕಿ ಎಂದು ತೋರಿಸುವುದನ್ನು ನಿಲ್ಲಿಸುತ್ತದೆ.',
  'No return is waiting to be filed.': 'ಫೈಲ್ ಮಾಡಲು ಯಾವ ರಿಟರ್ನ್ ಕೂಡ ಬಾಕಿ ಇಲ್ಲ.',
