  'A CPIN is the fourteen-digit challan number from the GST portal. Leave it blank if you do not have it yet.': 'CPIN ಎಂದರೆ GST ಪೋರ್ಟಲ್‌ನಿಂದ ಸಿಗುವ 14 ಅಂಕಿಯ ಚಲನ್ ನಂಬರ್. ಇನ್ನೂ ಇಲ್ಲದಿದ್ದರೆ ಖಾಲಿ ಬಿಡಿ.',
  'Paid GST for {month}': '{month} ರ GST ಕಟ್ಟಲಾಗಿದೆ',
  'GST paid for {month}': '{month} ರ ಕಟ್ಟಿದ GST',
  '{amount} is to pay in cash after set-off. Record the challan you paid on the GST portal; MyCA posts the set-off and the payment, and pays nothing itself.': 'ಸೆಟ್-ಆಫ್ ನಂತರ {amount} ನಗದಿನಲ್ಲಿ ಕಟ್ಟಬೇಕು. GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಕಟ್ಟಿದ ಚಲನ್ ಬರೆಯಿರಿ; MyCA ಸೆಟ್-ಆಫ್ ಮತ್ತು ಪಾವತಿಯನ್ನು ಪೋಸ್ಟ್ ಮಾಡುತ್ತದೆ, ತಾನಾಗಿ ಏನನ್ನೂ ಕಟ್ಟುವುದಿಲ್ಲ.',
  'CPIN (optional)': 'CPIN (ಬೇಕಿದ್ದರೆ)',
  'The fourteen-digit challan number': '14 ಅಂಕಿಯ ಚಲನ್ ನಂಬರ್',
  'Paid on': 'ಪಾವತಿ ದಿನಾಂಕ',
  'Closing a year moves its income and expenses to capital as new entries and locks the books through its last day. Do it once your CA has signed the year off; nothing already posted changes.': 'ವರ್ಷ ಮುಚ್ಚಿದರೆ ಅದರ ಆದಾಯ ಮತ್ತು ಖರ್ಚು ಹೊಸ ಎಂಟ್ರಿಗಳಾಗಿ ಬಂಡವಾಳಕ್ಕೆ ಹೋಗುತ್ತವೆ ಮತ್ತು ಅದರ ಕೊನೆಯ ದಿನದವರೆಗೆ ಲೆಕ್ಕ ಲಾಕ್ ಆಗುತ್ತದೆ. ನಿಮ್ಮ CA ವರ್ಷಕ್ಕೆ ಒಪ್ಪಿಗೆ ಕೊಟ್ಟ ನಂತರ ಮಾಡಿ; ಈಗಾಗಲೇ ಪೋಸ್ಟ್ ಆದ ಯಾವುದೂ ಬದಲಾಗುವುದಿಲ್ಲ.',
  'Year {year}': 'ವರ್ಷ {year}',
  'Profit {amount} · closed {date}': 'ಲಾಭ {amount} · {date} ರಂದು ಮುಚ್ಚಿದೆ',
  'Loss {amount} · closed {date}': 'ನಷ್ಟ {amount} · {date} ರಂದು ಮುಚ್ಚಿದೆ',
  'Year to close': 'ಮುಚ್ಚಬೇಕಾದ ವರ್ಷ',
  'The financial year as 2025-26, or the calendar year as 2025 for a US business': 'ಹಣಕಾಸು ವರ್ಷ 2025-26 ರೀತಿ, ಅಥವಾ US ವ್ಯಾಪಾರಕ್ಕೆ ಕ್ಯಾಲೆಂಡರ್ ವರ್ಷ 2025 ರೀತಿ',
  'Close the year {year}': 'ವರ್ಷ {year} ರ ಲೆಕ್ಕ ಮುಚ್ಚಿ',
  'Preview the closing': 'ಮುಚ್ಚುವ ಮೊದಲು ನೋಡಿ',
  'Close it': 'ಮುಚ್ಚಿ',
  'The portal accepted every invoice.': 'ಪೋರ್ಟಲ್ ಎಲ್ಲಾ ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ಒಪ್ಪಿದೆ.',
  'The portal refused some invoices. Fix them and save again.': 'ಪೋರ್ಟಲ್ ಕೆಲವು ಇನ್‌ವಾಯ್ಸ್‌ಗಳನ್ನು ಒಪ್ಪಲಿಲ್ಲ. ಅವನ್ನು ಸರಿಪಡಿಸಿ ಮತ್ತೆ ಉಳಿಸಿ.',
  'The portal could not process the save. Save again.': 'ಪೋರ್ಟಲ್‌ಗೆ ಉಳಿಸುವಿಕೆ ಪ್ರೊಸೆಸ್ ಮಾಡಲು ಆಗಲಿಲ್ಲ. ಮತ್ತೆ ಉಳಿಸಿ.',
  'The portal is still processing. Check again in a minute.': 'ಪೋರ್ಟಲ್ ಇನ್ನೂ ಪ್ರೊಸೆಸ್ ಮಾಡುತ್ತಿದೆ. ಒಂದು ನಿಮಿಷದ ನಂತರ ಮತ್ತೆ ನೋಡಿ.',
  'The portal says: {status}.': 'ಪೋರ್ಟಲ್ ಹೇಳುತ್ತಿದೆ: {status}.',
  'Asking the portal for an OTP…': 'ಪೋರ್ಟಲ್‌ನಿಂದ OTP ಕೇಳುತ್ತಿದ್ದೇವೆ…',
  'The GST portal sent an OTP.': 'GST ಪೋರ್ಟಲ್ OTP ಕಳುಹಿಸಿದೆ.',
  'Checking the OTP…': 'OTP ಪರಿಶೀಲಿಸುತ್ತಿದ್ದೇವೆ…',
  'Connected to the GST portal.': 'GST ಪೋರ್ಟಲ್‌ಗೆ ಕನೆಕ್ಟ್ ಆಗಿದೆ.',
  'Disconnecting…': 'ಕನೆಕ್ಷನ್ ತೆಗೆಯುತ್ತಿದ್ದೇವೆ…',
  'Disconnected from the GST portal.': 'GST ಪೋರ್ಟಲ್ ಕನೆಕ್ಷನ್ ತೆಗೆಯಲಾಗಿದೆ.',
  'Checking the approval for this step…': 'ಈ ಹಂತದ ಅನುಮೋದನೆ ಪರಿಶೀಲಿಸುತ್ತಿದ್ದೇವೆ…',
  'This business is in live mode, so this step needs a second person. Asked for approval: an owner or your accountant, other than you, opens this return and taps the same step to approve it.': 'ಈ ವ್ಯಾಪಾರ ಲೈವ್ ಮೋಡ್‌ನಲ್ಲಿದೆ, ಹಾಗಾಗಿ ಈ ಹಂತಕ್ಕೆ ಎರಡನೇ ವ್ಯಕ್ತಿ ಬೇಕು. ಅನುಮೋದನೆ ಕೇಳಲಾಗಿದೆ: ನೀವಲ್ಲದೆ ಬೇರೆ ಮಾಲೀಕರು ಅಥವಾ ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಈ ರಿಟರ್ನ್ ತೆರೆದು ಅದೇ ಹಂತ ಟ್ಯಾಪ್ ಮಾಡಿ ಅನುಮೋದಿಸಬೇಕು.',
  'Waiting for an owner or your accountant, other than you, to approve this step.': 'ನೀವಲ್ಲದೆ ಬೇರೆ ಮಾಲೀಕರು ಅಥವಾ ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಈ ಹಂತ ಅನುಮೋದಿಸಲು ಕಾಯುತ್ತಿದೆ.',
  'Saving the {form} to the portal…': '{form} ಪೋರ್ಟಲ್‌ಗೆ ಉಳಿಸುತ್ತಿದ್ದೇವೆ…',
  'Saved to the portal. Read the tax the portal works out next.': 'ಪೋರ್ಟಲ್‌ಗೆ ಉಳಿಸಲಾಗಿದೆ. ಮುಂದೆ ಪೋರ್ಟಲ್ ಲೆಕ್ಕ ಹಾಕುವ ತೆರಿಗೆ ಓದಿ.',
  'Saved to the portal. Check it next.': 'ಪೋರ್ಟಲ್‌ಗೆ ಉಳಿಸಲಾಗಿದೆ. ಮುಂದೆ ಇದನ್ನು ಪರಿಶೀಲಿಸಿ.',
  'Reading the tax the portal works out…': 'ಪೋರ್ಟಲ್ ಲೆಕ್ಕ ಹಾಕಿದ ತೆರಿಗೆ ಓದುತ್ತಿದ್ದೇವೆ…',
  'The portal has worked out the tax. Pay it from credit and cash next.': 'ಪೋರ್ಟಲ್ ತೆರಿಗೆ ಲೆಕ್ಕ ಹಾಕಿದೆ. ಮುಂದೆ ಅದನ್ನು ಕ್ರೆಡಿಟ್ ಮತ್ತು ನಗದಿನಿಂದ ಕಟ್ಟಿ.',
  'Simulated: this is the test environment, so nothing reaches the GST portal.': 'ಸಿಮ್ಯುಲೇಶನ್: ಇದು ಟೆಸ್ಟ್ ಸಿಸ್ಟಮ್, ಹಾಗಾಗಿ GST ಪೋರ್ಟಲ್‌ಗೆ ಏನೂ ಹೋಗುವುದಿಲ್ಲ.',
  'Pay the GSTR-3B tax for {month}?': '{month} ರ GSTR-3B ತೆರಿಗೆ ಕಟ್ಟಬೇಕೇ?',
  'The portal uses your input tax credit first, then the cash ledger. This cannot be undone. Pay any cash shortfall by challan (PMT-06) before this step.': 'ಪೋರ್ಟಲ್ ಮೊದಲು ನಿಮ್ಮ ಇನ್‌ಪುಟ್ ಟ್ಯಾಕ್ಸ್ ಕ್ರೆಡಿಟ್ ಬಳಸುತ್ತದೆ, ನಂತರ ಕ್ಯಾಶ್ ಲೆಡ್ಜರ್. ಇದನ್ನು ಹಿಂತೆಗೆಯಲು ಆಗುವುದಿಲ್ಲ. ನಗದು ಕೊರತೆ ಇದ್ದರೆ ಈ ಹಂತಕ್ಕೆ ಮೊದಲು ಚಲನ್ (PMT-06) ಮೂಲಕ ಕಟ್ಟಿ.',
  'Pay': 'ಕಟ್ಟಿ',
  'Setting off the tax…': 'ತೆರಿಗೆ ಸೆಟ್-ಆಫ್ ಆಗುತ್ತಿದೆ…',
  'Tax set off: {credit} from credit and {cash} from cash. Send the EVC OTP next.': 'ತೆರಿಗೆ ಸೆಟ್-ಆಫ್ ಆಯಿತು: ಕ್ರೆಡಿಟ್‌ನಿಂದ {credit} ಮತ್ತು ನಗದಿನಿಂದ {cash}. ಮುಂದೆ EVC OTP ಕಳುಹಿಸಿ.',
  'Checking with the portal…': 'ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಪರಿಶೀಲಿಸುತ್ತಿದ್ದೇವೆ…',
  'Submitting…': 'ಸಬ್ಮಿಟ್ ಆಗುತ್ತಿದೆ…',
  'Submitted. Read the portal summary before filing.': 'ಸಬ್ಮಿಟ್ ಆಯಿತು. ಫೈಲ್ ಮಾಡುವ ಮೊದಲು ಪೋರ್ಟಲ್ ಸಾರಾಂಶ ಓದಿ.',
  'Reading the portal summary…': 'ಪೋರ್ಟಲ್ ಸಾರಾಂಶ ಓದುತ್ತಿದ್ದೇವೆ…',
  'Asking the portal for the EVC OTP…': 'ಪೋರ್ಟಲ್‌ನಿಂದ EVC OTP ಕೇಳುತ್ತಿದ್ದೇವೆ…',
  'The portal sent the EVC OTP to the authorised signatory.': 'ಪೋರ್ಟಲ್ ಅಧಿಕೃತ ಸಹಿದಾರರಿಗೆ EVC OTP ಕಳುಹಿಸಿದೆ.',
  'File {form} for {month}?': '{month} ರ {form} ಫೈಲ್ ಮಾಡಬೇಕೇ?',
  'Filing cannot be undone. Check the tax and the credit first.': 'ಫೈಲ್ ಮಾಡಿದ ನಂತರ ಹಿಂತೆಗೆಯಲು ಆಗುವುದಿಲ್ಲ. ಮೊದಲು ತೆರಿಗೆ ಮತ್ತು ಕ್ರೆಡಿಟ್ ಪರಿಶೀಲಿಸಿ.',
  'Filing cannot be undone. Check the portal summary first.': 'ಫೈಲ್ ಮಾಡಿದ ನಂತರ ಹಿಂತೆಗೆಯಲು ಆಗುವುದಿಲ್ಲ. ಮೊದಲು ಪೋರ್ಟಲ್ ಸಾರಾಂಶ ಪರಿಶೀಲಿಸಿ.',
  'File': 'ಫೈಲ್ ಮಾಡಿ',
  'Filing…': 'ಫೈಲ್ ಆಗುತ್ತಿದೆ…',
  'Filed (simulated). Reference {ack} is practice only: nothing was sent to the GST portal.': 'ಫೈಲ್ ಆಯಿತು (ಸಿಮ್ಯುಲೇಶನ್). ರೆಫರೆನ್ಸ್ {ack} ಅಭ್ಯಾಸಕ್ಕೆ ಮಾತ್ರ: GST ಪೋರ್ಟಲ್‌ಗೆ ಏನೂ ಕಳುಹಿಸಿಲ್ಲ.',
  'Filed. Acknowledgement {ack}.': 'ಫೈಲ್ ಆಯಿತು. ಅಕ್ನಾಲೆಜ್‌ಮೆಂಟ್ {ack}.',
  'File on the GST portal': 'GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಫೈಲ್ ಮಾಡಿ',
  'Refresh': 'ರಿಫ್ರೆಶ್',
  '{form} for {month} · {gstin}': '{month} ರ {form} · {gstin}',
  'Practice mode: nothing is sent to the GST portal.': 'ಅಭ್ಯಾಸ ಮೋಡ್: GST ಪೋರ್ಟಲ್‌ಗೆ ಏನೂ ಕಳುಹಿಸುವುದಿಲ್ಲ.',
  'Test portal: this uses the GST sandbox, not your real return.': 'ಟೆಸ್ಟ್ ಪೋರ್ಟಲ್: ಇದು GST ಸ್ಯಾಂಡ್‌ಬಾಕ್ಸ್, ನಿಮ್ಮ ನಿಜವಾದ ರಿಟರ್ನ್ ಅಲ್ಲ.',
  'The portal session ended. Ask for a new OTP to reconnect.': 'ಪೋರ್ಟಲ್ ಸೆಶನ್ ಮುಗಿದಿದೆ. ಮತ್ತೆ ಕನೆಕ್ಟ್ ಆಗಲು ಹೊಸ OTP ಕೇಳಿ.',
  'Connect this GSTIN to the GST portal.': 'ಈ GSTIN ಅನ್ನು GST ಪೋರ್ಟಲ್‌ಗೆ ಕನೆಕ್ಟ್ ಮಾಡಿ.',
  'First, on gst.gov.in open My Profile → Manage API Access and turn API access on.': 'ಮೊದಲು gst.gov.in ನಲ್ಲಿ My Profile → Manage API Access ತೆರೆದು API access ಆನ್ ಮಾಡಿ.',
