  'Connected as {user} until {time}. MyCA keeps the session alive while API access stays on.': '{time} ವರೆಗೆ {user} ಆಗಿ ಕನೆಕ್ಟ್ ಆಗಿದೆ. API access ಆನ್ ಇರುವವರೆಗೆ MyCA ಸೆಶನ್ ಚಾಲೂ ಇಡುತ್ತದೆ.',
