  '{amount} of TDS is still to deposit. Record a challan paid on the income-tax portal or at the bank. MyCA pays nothing itself.': 'ಇನ್ನೂ {amount} TDS ಜಮಾ ಮಾಡಬೇಕು. ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಥವಾ ಬ್ಯಾಂಕ್‌ನಲ್ಲಿ ಕಟ್ಟಿದ ಚಲನ್ ಬರೆಯಿರಿ. MyCA ತಾನಾಗಿ ಏನನ್ನೂ ಕಟ್ಟುವುದಿಲ್ಲ.',
