  'Import Form 26AS from the income-tax portal (CSV or text) to compare it with your books.': 'ನಿಮ್ಮ ಲೆಕ್ಕದ ಜೊತೆ ಹೋಲಿಸಲು ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ಪೋರ್ಟಲ್‌ನಿಂದ Form 26AS (CSV ಅಥವಾ ಟೆಕ್ಸ್ಟ್) ಇಂಪೋರ್ಟ್ ಮಾಡಿ.',
