  'Review the return': 'ರಿಟರ್ನ್ ಪರಿಶೀಲಿಸಿ',
  'The review could not be loaded.': 'ಪರಿಶೀಲನೆ ತೆರೆಯಲು ಆಗಲಿಲ್ಲ.',
  'There is nothing dated in {month} to review.': '{month} ನಲ್ಲಿ ಪರಿಶೀಲಿಸಲು ಯಾವ ಎಂಟ್ರಿಯೂ ಇಲ್ಲ.',
  'You approved these figures on {date}.': 'ನೀವು ಈ ಅಂಕೆಗಳನ್ನು {date} ರಂದು ಅನುಮೋದಿಸಿದ್ದೀರಿ.',
  'Check each part. Nothing is filed from here.': 'ಪ್ರತಿ ಭಾಗ ಪರಿಶೀಲಿಸಿ. ಇಲ್ಲಿಂದ ಏನೂ ಫೈಲ್ ಆಗುವುದಿಲ್ಲ.',
  'Your books for this month changed after you last confirmed, so the review starts again.': 'ನೀವು ಕೊನೆಯ ಬಾರಿ ಖಚಿತಪಡಿಸಿದ ನಂತರ ಈ ತಿಂಗಳ ಲೆಕ್ಕ ಬದಲಾಗಿದೆ, ಹಾಗಾಗಿ ಪರಿಶೀಲನೆ ಮತ್ತೆ ಶುರುವಾಗುತ್ತದೆ.',
  'the {month} return': '{month} ರ ರಿಟರ್ನ್',
  'Ask my CA about {month}': '{month} ಬಗ್ಗೆ ನನ್ನ CA ಯನ್ನು ಕೇಳಿ',
  'Next: save the GSTR-1 file from Taxes and upload it on the GST portal, or send it to your CA.': 'ಮುಂದೆ: ತೆರಿಗೆ ವಿಭಾಗದಿಂದ GSTR-1 ಫೈಲ್ ಉಳಿಸಿ GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, ಅಥವಾ ನಿಮ್ಮ CA ಗೆ ಕಳುಹಿಸಿ.',
  'Approved': 'ಅನುಮೋದಿಸಲಾಗಿದೆ',
  'Confirmed': 'ಖಚಿತವಾಗಿದೆ',
  'Marked not right': 'ಸರಿಯಿಲ್ಲ ಎಂದು ಗುರುತಿಸಲಾಗಿದೆ',
  'Marked not right: {note}': 'ಸರಿಯಿಲ್ಲ ಎಂದು ಗುರುತಿಸಲಾಗಿದೆ: {note}',
  'Waiting for the step above': 'ಮೇಲಿನ ಹಂತಕ್ಕಾಗಿ ಕಾಯುತ್ತಿದೆ',
  'What is not right?': 'ಏನು ಸರಿಯಿಲ್ಲ?',
  'Fix the entry in its chat. When the figures change, this step opens again.': 'ಎಂಟ್ರಿಯನ್ನು ಅದರ ಚಾಟ್‌ನಲ್ಲಿ ಸರಿಪಡಿಸಿ. ಅಂಕೆಗಳು ಬದಲಾದಾಗ ಈ ಹಂತ ಮತ್ತೆ ತೆರೆಯುತ್ತದೆ.',
  'Note for yourself or your CA (optional)': 'ನಿಮಗಾಗಿ ಅಥವಾ ನಿಮ್ಮ CA ಗಾಗಿ ನೋಟ್ (ಬೇಕಿದ್ದರೆ)',
  'Mark as not right': 'ಸರಿಯಿಲ್ಲ ಎಂದು ಗುರುತಿಸಿ',
  'Approve payroll for {month}': '{month} ರ ಸಂಬಳ ಅನುಮೋದಿಸಿ',
  'No provident fund member in this month.': 'ಈ ತಿಂಗಳು PF ನಲ್ಲಿ ಯಾರೂ ಇಲ್ಲ.',
  'No state insurance member in this month.': 'ಈ ತಿಂಗಳು ESI ನಲ್ಲಿ ಯಾರೂ ಇಲ್ಲ.',
  'Saved {name}. Upload it on the EPFO portal and pay the challan.': '{name} ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು EPFO ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಚಲನ್ ಕಟ್ಟಿ.',
  'Saved {name}. Upload it on the ESIC portal and pay the challan.': '{name} ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು ESIC ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಚಲನ್ ಕಟ್ಟಿ.',
  'No UAN for {names}; add it on the employee first.': '{names} ಗೆ UAN ಇಲ್ಲ; ಮೊದಲು ಉದ್ಯೋಗಿಯ ವಿವರದಲ್ಲಿ ಸೇರಿಸಿ.',
  'No insurance number for {names}; add it on the employee first.': '{names} ಗೆ ESI ನಂಬರ್ ಇಲ್ಲ; ಮೊದಲು ಉದ್ಯೋಗಿಯ ವಿವರದಲ್ಲಿ ಸೇರಿಸಿ.',
  'Nothing to pay out this month.': 'ಈ ತಿಂಗಳು ಯಾರಿಗೂ ಹಣ ಕೊಡಬೇಕಿಲ್ಲ.',
  'Saved {name} with 1 employee, {total}. Upload it on the bank\'s bulk payment page, then record the salary payment here.': '{name} 1 ಉದ್ಯೋಗಿ, {total} ಜೊತೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು ಬ್ಯಾಂಕ್‌ನ ಬಲ್ಕ್ ಪೇಮೆಂಟ್ ಪುಟದಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, ನಂತರ ಇಲ್ಲಿ ಸಂಬಳ ಪಾವತಿ ಬರೆಯಿರಿ.',
  'Saved {name} with {n} employees, {total}. Upload it on the bank\'s bulk payment page, then record the salary payment here.': '{name} {n} ಉದ್ಯೋಗಿಗಳು, {total} ಜೊತೆ ಉಳಿಸಲಾಗಿದೆ. ಇದನ್ನು ಬ್ಯಾಂಕ್‌ನ ಬಲ್ಕ್ ಪೇಮೆಂಟ್ ಪುಟದಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, ನಂತರ ಇಲ್ಲಿ ಸಂಬಳ ಪಾವತಿ ಬರೆಯಿರಿ.',
  'No bank account for {names}; add it on the employee first.': '{names} ಗೆ ಬ್ಯಾಂಕ್ ಖಾತೆ ಇಲ್ಲ; ಮೊದಲು ಉದ್ಯೋಗಿಯ ವಿವರದಲ್ಲಿ ಸೇರಿಸಿ.',
  'No approved salary month in this year yet, so Annexure II has no rows.': 'ಈ ವರ್ಷ ಇನ್ನೂ ಯಾವ ತಿಂಗಳ ಸಂಬಳವೂ ಅನುಮೋದನೆ ಆಗಿಲ್ಲ, ಹಾಗಾಗಿ Annexure II ನಲ್ಲಿ ಸಾಲುಗಳಿಲ್ಲ.',
  'Saved {name} with 1 employee. Add each employee\'s declaration (section 10 exemptions, other 80C and 80D) before filing the Q4 statement.': '{name} 1 ಉದ್ಯೋಗಿಯೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. Q4 ಸ್ಟೇಟ್‌ಮೆಂಟ್ ಫೈಲ್ ಮಾಡುವ ಮೊದಲು ಪ್ರತಿ ಉದ್ಯೋಗಿಯ ಡಿಕ್ಲರೇಶನ್ (ಸೆಕ್ಷನ್ 10 ವಿನಾಯಿತಿ, ಇತರ 80C ಮತ್ತು 80D) ಸೇರಿಸಿ.',
  'Saved {name} with {n} employees. Add each employee\'s declaration (section 10 exemptions, other 80C and 80D) before filing the Q4 statement.': '{name} {n} ಉದ್ಯೋಗಿಗಳೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. Q4 ಸ್ಟೇಟ್‌ಮೆಂಟ್ ಫೈಲ್ ಮಾಡುವ ಮೊದಲು ಪ್ರತಿ ಉದ್ಯೋಗಿಯ ಡಿಕ್ಲರೇಶನ್ (ಸೆಕ್ಷನ್ 10 ವಿನಾಯಿತಿ, ಇತರ 80C ಮತ್ತು 80D) ಸೇರಿಸಿ.',
  'No Form 16 draft yet: approve a salary month with TDS first, and record the TAN under Taxes.': 'ಇನ್ನೂ Form 16 ಡ್ರಾಫ್ಟ್ ಇಲ್ಲ: ಮೊದಲು TDS ಇರುವ ಒಂದು ತಿಂಗಳ ಸಂಬಳ ಅನುಮೋದಿಸಿ, ಮತ್ತು ತೆರಿಗೆ ವಿಭಾಗದಲ್ಲಿ TAN ಬರೆಯಿರಿ.',
  'Saved {name} with 1 employee. Part A comes from TRACES after the 24Q statements are processed; these are the books\' own figures for checking.': '{name} 1 ಉದ್ಯೋಗಿಯೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. 24Q ಸ್ಟೇಟ್‌ಮೆಂಟ್‌ಗಳು ಪ್ರೊಸೆಸ್ ಆದ ನಂತರ Part A TRACES ಇಂದ ಬರುತ್ತದೆ; ಇವು ಪರಿಶೀಲನೆಗಾಗಿ ಲೆಕ್ಕದ ಸ್ವಂತ ಅಂಕೆಗಳು.',
  'Saved {name} with {n} employees. Part A comes from TRACES after the 24Q statements are processed; these are the books\' own figures for checking.': '{name} {n} ಉದ್ಯೋಗಿಗಳೊಂದಿಗೆ ಉಳಿಸಲಾಗಿದೆ. 24Q ಸ್ಟೇಟ್‌ಮೆಂಟ್‌ಗಳು ಪ್ರೊಸೆಸ್ ಆದ ನಂತರ Part A TRACES ಇಂದ ಬರುತ್ತದೆ; ಇವು ಪರಿಶೀಲನೆಗಾಗಿ ಲೆಕ್ಕದ ಸ್ವಂತ ಅಂಕೆಗಳು.',
  'Salaries for {month} paid': '{month} ರ ಸಂಬಳ ಕೊಡಲಾಗಿದೆ',
