  'A Udyam number looks like UDYAM-XX-00-0000000.': 'ಉದ್ಯಮ್ ನಂಬರ್ ಹೀಗಿರುತ್ತದೆ: UDYAM-XX-00-0000000.',
  'Agreed days must be a whole number from 0 to 365.': 'ಒಪ್ಪಿದ ದಿನಗಳು 0 ರಿಂದ 365 ರ ಪೂರ್ಣ ಸಂಖ್ಯೆ ಆಗಿರಬೇಕು.',
  'An MSME supplier must be paid within 45 days, so the agreed days cannot be more than 45.': 'MSME ಸಪ್ಲೈಯರ್‌ಗೆ 45 ದಿನದೊಳಗೆ ಪಾವತಿಸಬೇಕು, ಹಾಗಾಗಿ ಒಪ್ಪಿದ ದಿನಗಳು 45 ಕ್ಕಿಂತ ಹೆಚ್ಚು ಇರಬಾರದು.',
  'Switch on MSME supplier, or give the agreed days.': 'MSME ಸಪ್ಲೈಯರ್ ಆನ್ ಮಾಡಿ, ಅಥವಾ ಒಪ್ಪಿದ ದಿನಗಳನ್ನು ಹಾಕಿ.',
  'Terms for {name}': '{name} ಅವರ ಷರತ್ತುಗಳು',
  'A micro or small supplier has to be paid within 45 days of the bill. MyCA reminds you a week before.': 'ಮೈಕ್ರೋ ಅಥವಾ ಸ್ಮಾಲ್ ಸಪ್ಲೈಯರ್‌ಗೆ ಬಿಲ್‌ನ 45 ದಿನದೊಳಗೆ ಪಾವತಿಸಬೇಕು. MyCA ಒಂದು ವಾರ ಮುಂಚೆ ನೆನಪಿಸುತ್ತದೆ.',
  'Udyam number': 'ಉದ್ಯಮ್ ನಂಬರ್',
  'The 45-day rule covers micro and small suppliers only.': '45 ದಿನದ ನಿಯಮ ಮೈಕ್ರೋ ಮತ್ತು ಸ್ಮಾಲ್ ಸಪ್ಲೈಯರ್‌ಗಳಿಗೆ ಮಾತ್ರ.',
  'Agreed days': 'ಒಪ್ಪಿದ ದಿನಗಳು',
  'Up to 45. Leave it empty for the 15 days the law gives without a written agreement.': '45 ವರೆಗೆ. ಲಿಖಿತ ಒಪ್ಪಂದ ಇಲ್ಲದಿದ್ದರೆ ಕಾನೂನು ಕೊಡುವ 15 ದಿನಕ್ಕೆ ಖಾಲಿ ಬಿಡಿ.',
  'How many days you have to pay their bills.': 'ಅವರ ಬಿಲ್ ಪಾವತಿಸಲು ನಿಮಗೆ ಎಷ್ಟು ದಿನ ಇದೆ.',
  'Enter how much TDS the customer withheld.': 'ಗ್ರಾಹಕರು ಎಷ್ಟು TDS ಕಡಿತ ಮಾಡಿದರು ಹಾಕಿ.',
  'A TAN looks like MUMA12345B.': 'TAN ಹೀಗಿರುತ್ತದೆ: MUMA12345B.',
  'TDS withheld by {name}': '{name} ಕಡಿತ ಮಾಡಿದ TDS',
  'The customer paid you less because they deducted TDS. The invoice settles by this amount, and the credit waits in TDS receivable until Form 26AS confirms it.': 'ಗ್ರಾಹಕರು TDS ಕಡಿತ ಮಾಡಿದ್ದರಿಂದ ನಿಮಗೆ ಕಡಿಮೆ ಕೊಟ್ಟಿದ್ದಾರೆ. ಇನ್‌ವಾಯ್ಸ್ ಈ ಮೊತ್ತದಷ್ಟು ಚುಕ್ತಾ ಆಗುತ್ತದೆ, Form 26AS ಖಚಿತಪಡಿಸುವವರೆಗೆ ಕ್ರೆಡಿಟ್ TDS ರಿಸೀವೇಬಲ್‌ನಲ್ಲಿ ಕಾಯುತ್ತದೆ.',
  'Filled in at 2% of the invoice. Change it to what the customer deducted.': 'ಇನ್‌ವಾಯ್ಸ್‌ನ 2% ತುಂಬಲಾಗಿದೆ. ಗ್ರಾಹಕರು ಕಡಿತ ಮಾಡಿದಷ್ಟಕ್ಕೆ ಬದಲಿಸಿ.',
  'Section': 'ಸೆಕ್ಷನ್',
  'Withheld on': 'ಕಡಿತವಾದ ದಿನಾಂಕ',
  'Customer\'s TAN (optional)': 'ಗ್ರಾಹಕರ TAN (ಬೇಕಿದ್ದರೆ)',
  'On the TDS certificate, like MUMA12345B. It lets Form 26AS match this row.': 'TDS ಸರ್ಟಿಫಿಕೇಟ್‌ನಲ್ಲಿ ಇರುತ್ತದೆ, ಉದಾ MUMA12345B. ಇದರಿಂದ Form 26AS ಈ ಸಾಲನ್ನು ಹೊಂದಿಸುತ್ತದೆ.',
  'Type the customer name': 'ಗ್ರಾಹಕರ ಹೆಸರು ಟೈಪ್ ಮಾಡಿ',
  'Type the supplier name': 'ಸಪ್ಲೈಯರ್ ಹೆಸರು ಟೈಪ್ ಮಾಡಿ',
