  'firm': 'ಖಡಕ್',
  '{name} has nothing overdue, or paid something in the last two weeks. Match your bank statement before chasing.': '{name} ಅವರದ್ದು ಏನೂ ಬಾಕಿ ಮೀರಿಲ್ಲ, ಅಥವಾ ಕಳೆದ ಎರಡು ವಾರದಲ್ಲಿ ಏನೋ ಪಾವತಿಸಿದ್ದಾರೆ. ಕೇಳುವ ಮೊದಲು ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ಸ್ಟೇಟ್‌ಮೆಂಟ್ ಹೊಂದಿಸಿ.',
  '{name} {score}, so this draft is {tone}.': '{name} {score}, ಹಾಗಾಗಿ ಈ ಮೆಸೇಜ್‌ನ ಧಾಟಿ {tone}.',
  'You reminded them on {date} ({n} times so far).': 'ನೀವು {date} ರಂದು ನೆನಪಿಸಿದ್ದೀರಿ (ಇಲ್ಲಿಯವರೆಗೆ {n} ಬಾರಿ).',
  'You reminded them on {date}.': 'ನೀವು {date} ರಂದು ನೆನಪಿಸಿದ್ದೀರಿ.',
  '{amount} overdue across 1 invoice, oldest {days} days late.': '1 ಇನ್‌ವಾಯ್ಸ್‌ನಲ್ಲಿ {amount} ಬಾಕಿ ಮೀರಿದೆ, ಹಳೆಯದು {days} ದಿನ ತಡ.',
  '{amount} overdue across {n} invoices, oldest {days} days late.': '{n} ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ {amount} ಬಾಕಿ ಮೀರಿದೆ, ಹಳೆಯದು {days} ದಿನ ತಡ.',
  'Your phone offered the message to WhatsApp, email or another app. MyCA will remind you to check for the payment in a week.': 'ನಿಮ್ಮ ಫೋನ್ ಮೆಸೇಜನ್ನು WhatsApp, ಇಮೇಲ್ ಅಥವಾ ಬೇರೆ ಆ್ಯಪ್‌ಗೆ ಕೊಟ್ಟಿದೆ. ಒಂದು ವಾರದಲ್ಲಿ ಪಾವತಿ ಬಂತೇ ನೋಡಲು MyCA ನೆನಪಿಸುತ್ತದೆ.',
  'Your phone could not open the share sheet. Copy the message and send it yourself.': 'ನಿಮ್ಮ ಫೋನ್‌ಗೆ ಶೇರ್ ಆಯ್ಕೆ ತೆರೆಯಲು ಆಗಲಿಲ್ಲ. ಮೆಸೇಜ್ ಕಾಪಿ ಮಾಡಿ ನೀವೇ ಕಳುಹಿಸಿ.',
  'Send this reminder from my phone': 'ಈ ರಿಮೈಂಡರ್ ನನ್ನ ಫೋನ್‌ನಿಂದ ಕಳುಹಿಸಿ',
  'Remind supplier': 'ಸಪ್ಲೈಯರ್‌ಗೆ ನೆನಪಿಸಿ',
  'There is nothing to ask this supplier for this month.': 'ಈ ತಿಂಗಳು ಈ ಸಪ್ಲೈಯರ್‌ನಿಂದ ಕೇಳಲು ಏನೂ ಇಲ್ಲ.',
  'Only their own bill numbers, dates and amounts. Edit it as you like.': 'ಅವರದೇ ಬಿಲ್ ನಂಬರ್, ದಿನಾಂಕ ಮತ್ತು ಮೊತ್ತ ಮಾತ್ರ. ಬೇಕಾದಂತೆ ಬದಲಿಸಿ.',
  '1 bill for {month} · {credit} of your input credit waiting': '{month} ರ 1 ಬಿಲ್ · ನಿಮ್ಮ {credit} ಇನ್‌ಪುಟ್ ಕ್ರೆಡಿಟ್ ಕಾಯುತ್ತಿದೆ',
  '{n} bills for {month} · {credit} of your input credit waiting': '{month} ರ {n} ಬಿಲ್‌ಗಳು · ನಿಮ್ಮ {credit} ಇನ್‌ಪುಟ್ ಕ್ರೆಡಿಟ್ ಕಾಯುತ್ತಿದೆ',
  'Your phone offered the message to WhatsApp, email or another app.': 'ನಿಮ್ಮ ಫೋನ್ ಮೆಸೇಜನ್ನು WhatsApp, ಇಮೇಲ್ ಅಥವಾ ಬೇರೆ ಆ್ಯಪ್‌ಗೆ ಕೊಟ್ಟಿದೆ.',
  'Recorded. Make the transfers from your bank app; MyCA has posted the payments against each bill.': 'ದಾಖಲಾಯಿತು. ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ಆ್ಯಪ್‌ನಿಂದ ಹಣ ಕಳುಹಿಸಿ; MyCA ಪ್ರತಿ ಬಿಲ್ ವಿರುದ್ಧ ಪಾವತಿ ಪೋಸ್ಟ್ ಮಾಡಿದೆ.',
  'Pay the chosen bills from the bank': 'ಆಯ್ಕೆಮಾಡಿದ ಬಿಲ್‌ಗಳನ್ನು ಬ್ಯಾಂಕ್‌ನಿಂದ ಪಾವತಿಸಿ',
  'Who to pay': 'ಯಾರಿಗೆ ಪಾವತಿಸಬೇಕು',
  'The payment run could not be worked out.': 'ಪಾವತಿ ಪಟ್ಟಿ ಲೆಕ್ಕ ಹಾಕಲು ಆಗಲಿಲ್ಲ.',
  'Pay now': 'ಈಗ ಪಾವತಿಸಿ',
  'MSMED pay-by dates first, then bills near the 180-day credit limit, then agreed terms.': 'ಮೊದಲು MSMED ಕೊನೆಯ ದಿನಾಂಕದವು, ನಂತರ 180 ದಿನದ ಕ್ರೆಡಿಟ್ ಮಿತಿ ಹತ್ತಿರದ ಬಿಲ್‌ಗಳು, ನಂತರ ಒಪ್ಪಿದ ಷರತ್ತುಗಳು.',
  'Consider': 'ಇವನ್ನೂ ಪರಿಗಣಿಸಿ',
  'Older than 45 days with no agreed terms.': '45 ದಿನಕ್ಕಿಂತ ಹಳೆಯದು, ಯಾವ ಷರತ್ತೂ ಒಪ್ಪಿಲ್ಲ.',
  'Held back': 'ತಡೆಹಿಡಿದವು',
  'Yes, pay them': 'ಹೌದು, ಪಾವತಿಸಿ',
  '{bill} (their {theirs}) · {when}': '{bill} (ಅವರದು {theirs}) · {when}',
  'Nothing needs paying in the next {days} days.': 'ಮುಂದಿನ {days} ದಿನದಲ್ಲಿ ಏನೂ ಪಾವತಿಸಬೇಕಿಲ್ಲ.',
  '{supplier} {amount} on {bill}: {reason}': '{supplier} {amount}, {bill} ಮೇಲೆ: {reason}',
  'Bank and cash {balance} now, {after} after paying {chosen}.': 'ಈಗ ಬ್ಯಾಂಕ್ ಮತ್ತು ನಗದು {balance}, {chosen} ಪಾವತಿಸಿದ ನಂತರ {after}.',
  'MyCA has only the recorded figures for bank and cash ({balance}). Give your balance on the Cash screen for a true picture.': 'MyCA ಬಳಿ ಬ್ಯಾಂಕ್ ಮತ್ತು ನಗದಿನ ದಾಖಲಾದ ಅಂಕೆಗಳು ಮಾತ್ರ ಇವೆ ({balance}). ನಿಜವಾದ ಚಿತ್ರಕ್ಕಾಗಿ ನಗದು ಸ್ಕ್ರೀನ್‌ನಲ್ಲಿ ನಿಮ್ಮ ಬ್ಯಾಲೆನ್ಸ್ ಕೊಡಿ.',
  'Pay {amount} from the bank': 'ಬ್ಯಾಂಕ್‌ನಿಂದ {amount} ಪಾವತಿಸಿ',
  '1 bill ({amount}) can wait.': '1 ಬಿಲ್ ({amount}) ನಂತರ ಕೊಡಬಹುದು.',
  '{n} bills ({amount}) can wait.': '{n} ಬಿಲ್‌ಗಳು ({amount}) ನಂತರ ಕೊಡಬಹುದು.',
  'Invoice': 'ಇನ್‌ವಾಯ್ಸ್',
  'Quotation': 'ಕೊಟೇಶನ್',
  'Proforma invoice {id}': 'ಪ್ರೊಫಾರ್ಮಾ ಇನ್‌ವಾಯ್ಸ್ {id}',
  'Sales order {id}': 'ಸೇಲ್ಸ್ ಆರ್ಡರ್ {id}',
  'Delivery challan {id}': 'ಡೆಲಿವರಿ ಚಲನ್ {id}',
  'Quote {id}': 'ಕೊಟೇಶನ್ {id}',
  'Overdue by 1 day': '1 ದಿನದಿಂದ ಬಾಕಿ',
  'your GSTIN': 'ನಿಮ್ಮ GSTIN',
  'your business address': 'ನಿಮ್ಮ ವ್ಯಾಪಾರದ ವಿಳಾಸ',
  'an HSN or SAC code on every item': 'ಪ್ರತಿ ಐಟಂಗೆ HSN ಅಥವಾ SAC ಕೋಡ್',
  '{first} and {last}': '{first} ಮತ್ತು {last}',
  'This invoice does not carry {list}. Check with your CA whether your buyer needs it before you send this.': 'ಈ ಇನ್‌ವಾಯ್ಸ್‌ನಲ್ಲಿ {list} ಇಲ್ಲ. ಕಳುಹಿಸುವ ಮೊದಲು ನಿಮ್ಮ ಖರೀದಿದಾರರಿಗೆ ಅದು ಬೇಕೇ ಎಂದು ನಿಮ್ಮ CA ಬಳಿ ಕೇಳಿ.',
  'Credit note for the whole of {id}: {reason}': 'ಪೂರ್ತಿ {id} ಗೆ ಕ್ರೆಡಿಟ್ ನೋಟ್: {reason}',
  'Credit note of {amount} against {id}: {reason}': '{id} ವಿರುದ್ಧ {amount} ಕ್ರೆಡಿಟ್ ನೋಟ್: {reason}',
  'Debit note of {amount} against {id}: {reason}': '{id} ವಿರುದ್ಧ {amount} ಡೆಬಿಟ್ ನೋಟ್: {reason}',
  'Amend {id}: {reason}': '{id} ತಿದ್ದುಪಡಿ: {reason}',
  'Transport for {id}: {vehicle} {km} km': '{id} ಗೆ ಸಾರಿಗೆ: {vehicle} {km} ಕಿಮೀ',
  'Generate the e-invoice (IRN) for {id}': '{id} ಗೆ ಇ-ಇನ್‌ವಾಯ್ಸ್ (IRN) ಮಾಡಿ',
  'Generate the e-way bill for {id}': '{id} ಗೆ ಇ-ವೇ ಬಿಲ್ ಮಾಡಿ',
  'This business is in live mode, so a real IRN needs a second person. Asked for approval: an owner or your accountant opens this invoice and taps Generate e-invoice to approve it.': 'ಈ ವ್ಯಾಪಾರ ಲೈವ್ ಮೋಡ್‌ನಲ್ಲಿದೆ, ಹಾಗಾಗಿ ನಿಜವಾದ IRN ಗೆ ಎರಡನೇ ವ್ಯಕ್ತಿ ಬೇಕು. ಅನುಮೋದನೆ ಕೇಳಲಾಗಿದೆ: ಮಾಲೀಕರು ಅಥವಾ ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಈ ಇನ್‌ವಾಯ್ಸ್ ತೆರೆದು ಇ-ಇನ್‌ವಾಯ್ಸ್ ಮಾಡಿ ಟ್ಯಾಪ್ ಮಾಡಿ ಅನುಮೋದಿಸಬೇಕು.',
  'Waiting for an owner or your accountant, other than you, to approve this e-invoice.': 'ನೀವಲ್ಲದೆ ಬೇರೆ ಮಾಲೀಕರು ಅಥವಾ ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಈ ಇ-ಇನ್‌ವಾಯ್ಸ್ ಅನುಮೋದಿಸಲು ಕಾಯುತ್ತಿದೆ.',
  'Sandbox IRN issued on the NIC test IRP. It is not valid for a real supply.': 'NIC ಟೆಸ್ಟ್ IRP ಯಲ್ಲಿ ಸ್ಯಾಂಡ್‌ಬಾಕ್ಸ್ IRN ಆಗಿದೆ. ಇದು ನಿಜವಾದ ಸರಬರಾಜಿಗೆ ಮಾನ್ಯವಲ್ಲ.',
  'IRN issued: {irn}': 'IRN ಆಗಿದೆ: {irn}',
  'invoice {id} to {name}': '{name} ಗೆ ಇನ್‌ವಾಯ್ಸ್ {id}',
  'Follow up payment from {name}': '{name} ಇಂದ ಪಾವತಿಗಾಗಿ ಫಾಲೋ-ಅಪ್',
  'Cancel {id}': '{id} ರದ್ದುಮಾಡಿ',
  'Cancel {id}: {reason}': '{id} ರದ್ದುಮಾಡಿ: {reason}',
  'Cancel {id}?': '{id} ರದ್ದುಮಾಡಬೇಕೇ?',
  'Handed to the app you chose. MyCA cannot see whether it was delivered.': 'ನೀವು ಆಯ್ಕೆಮಾಡಿದ ಆ್ಯಪ್‌ಗೆ ಕೊಡಲಾಗಿದೆ. ತಲುಪಿತೇ ಎಂದು MyCA ಗೆ ಕಾಣುವುದಿಲ್ಲ.',
  '{note} Could not note the share in the audit log.': '{note} ಶೇರ್ ಮಾಡಿದ್ದನ್ನು ಆಡಿಟ್ ಲಾಗ್‌ನಲ್ಲಿ ಬರೆಯಲು ಆಗಲಿಲ್ಲ.',
  'The PDF could not be prepared on this phone.': 'ಈ ಫೋನ್‌ನಲ್ಲಿ PDF ತಯಾರಿಸಲು ಆಗಲಿಲ್ಲ.',
  'This invoice could not be opened.': 'ಈ ಇನ್‌ವಾಯ್ಸ್ ತೆರೆಯಲು ಆಗಲಿಲ್ಲ.',
  '{id} accepted': '{id} ಒಪ್ಪಿಗೆಯಾಗಿದೆ',
  '{id} declined': '{id} ನಿರಾಕರಿಸಲಾಗಿದೆ',
