  'This invoice is cancelled by a credit note. It stays in your books and in the return for its month.': 'ಈ ಇನ್‌ವಾಯ್ಸ್ ಕ್ರೆಡಿಟ್ ನೋಟ್‌ನಿಂದ ರದ್ದಾಗಿದೆ. ಇದು ನಿಮ್ಮ ಲೆಕ್ಕದಲ್ಲಿ ಮತ್ತು ಅದರ ತಿಂಗಳ ರಿಟರ್ನ್‌ನಲ್ಲಿ ಉಳಿಯುತ್ತದೆ.',
