  'Generate e-way bill': 'ಇ-ವೇ ಬಿಲ್ ಮಾಡಿ',
  'Shared once, last on {date}. Delivery is not something MyCA can know.': 'ಒಮ್ಮೆ ಶೇರ್ ಮಾಡಲಾಗಿದೆ, ಕೊನೆಯದಾಗಿ {date} ರಂದು. ತಲುಪಿತೇ ಎಂದು MyCA ಗೆ ತಿಳಿಯಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'Shared {n} times, last on {date}. Delivery is not something MyCA can know.': '{n} ಬಾರಿ ಶೇರ್ ಮಾಡಲಾಗಿದೆ, ಕೊನೆಯದಾಗಿ {date} ರಂದು. ತಲುಪಿತೇ ಎಂದು MyCA ಗೆ ತಿಳಿಯಲು ಸಾಧ್ಯವಿಲ್ಲ.',
  'Send to {name}': '{name} ಗೆ ಕಳುಹಿಸಿ',
  'Print or save as PDF': 'ಪ್ರಿಂಟ್ ಮಾಡಿ ಅಥವಾ PDF ಆಗಿ ಉಳಿಸಿ',
  'You choose WhatsApp, email or another app, and it goes from your own account. MyCA sends nothing by itself.': 'ನೀವು WhatsApp, ಇಮೇಲ್ ಅಥವಾ ಬೇರೆ ಆ್ಯಪ್ ಆಯ್ಕೆಮಾಡಿ, ಅದು ನಿಮ್ಮದೇ ಖಾತೆಯಿಂದ ಹೋಗುತ್ತದೆ. MyCA ತಾನಾಗಿ ಏನನ್ನೂ ಕಳುಹಿಸುವುದಿಲ್ಲ.',
  'Amend after filing': 'ಫೈಲಿಂಗ್ ನಂತರ ತಿದ್ದುಪಡಿ',
  'Make invoice': 'ಇನ್‌ವಾಯ್ಸ್ ಮಾಡಿ',
  'Goods came back': 'ಮಾಲು ವಾಪಸ್ ಬಂದಿದೆ',
  'This posts nothing to your books. Making the invoice posts it, with the same lines.': 'ಇದು ನಿಮ್ಮ ಲೆಕ್ಕಕ್ಕೆ ಏನನ್ನೂ ಪೋಸ್ಟ್ ಮಾಡುವುದಿಲ್ಲ. ಇನ್‌ವಾಯ್ಸ್ ಮಾಡಿದಾಗ ಅದೇ ಸಾಲುಗಳೊಂದಿಗೆ ಪೋಸ್ಟ್ ಆಗುತ್ತದೆ.',
  'Cancel invoice': 'ಇನ್‌ವಾಯ್ಸ್ ರದ್ದುಮಾಡಿ',
  'A credit note, a debit note or a cancellation changes the amount with a new entry; the invoice itself is never changed.': 'ಕ್ರೆಡಿಟ್ ನೋಟ್, ಡೆಬಿಟ್ ನೋಟ್ ಅಥವಾ ರದ್ದು ಹೊಸ ಎಂಟ್ರಿಯಿಂದ ಮೊತ್ತ ಬದಲಿಸುತ್ತದೆ; ಇನ್‌ವಾಯ್ಸ್ ಎಂದೂ ಬದಲಾಗುವುದಿಲ್ಲ.',
  'Transport for {id}': '{id} ಗೆ ಸಾರಿಗೆ',
  'How the goods move. MyCA puts this on the e-way bill request; nothing is sent until you approve it.': 'ಮಾಲು ಹೇಗೆ ಹೋಗುತ್ತದೆ. MyCA ಇದನ್ನು ಇ-ವೇ ಬಿಲ್ ಕೋರಿಕೆಯಲ್ಲಿ ಹಾಕುತ್ತದೆ; ನೀವು ಅನುಮೋದಿಸುವವರೆಗೆ ಏನೂ ಕಳುಹಿಸುವುದಿಲ್ಲ.',
  'Road': 'ರಸ್ತೆ',
  'Rail': 'ರೈಲು',
  'Air': 'ವಿಮಾನ',
  'Ship': 'ಹಡಗು',
  'Vehicle number': 'ವಾಹನ ನಂಬರ್',
  'Distance in km': 'ದೂರ (ಕಿಮೀ)',
  'Transporter (optional)': 'ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್ (ಬೇಕಿದ್ದರೆ)',
  'Enter the distance in whole kilometres, 1 to 4000.': 'ದೂರವನ್ನು ಪೂರ್ಣ ಕಿಲೋಮೀಟರ್‌ನಲ್ಲಿ ಹಾಕಿ, 1 ರಿಂದ 4000.',
  'Enter the vehicle number, for example MH12AB1234.': 'ವಾಹನ ನಂಬರ್ ಹಾಕಿ, ಉದಾಹರಣೆಗೆ MH12AB1234.',
  'Amend {id}': '{id} ತಿದ್ದುಪಡಿ',
  'For an invoice whose GSTR-1 month is already filed. The difference posts to the books and the amendment goes in the next GSTR-1 with the original number and date.': 'GSTR-1 ತಿಂಗಳು ಈಗಾಗಲೇ ಫೈಲ್ ಆದ ಇನ್‌ವಾಯ್ಸ್‌ಗಾಗಿ. ವ್ಯತ್ಯಾಸ ಲೆಕ್ಕಕ್ಕೆ ಪೋಸ್ಟ್ ಆಗುತ್ತದೆ, ತಿದ್ದುಪಡಿ ಮೂಲ ನಂಬರ್ ಮತ್ತು ದಿನಾಂಕದೊಂದಿಗೆ ಮುಂದಿನ GSTR-1 ನಲ್ಲಿ ಹೋಗುತ್ತದೆ.',
  'Say why the invoice is being amended.': 'ಇನ್‌ವಾಯ್ಸ್ ಯಾಕೆ ತಿದ್ದುಪಡಿ ಮಾಡಲಾಗುತ್ತಿದೆ ಎಂದು ಹೇಳಿ.',
  'Line {n} needs a quantity, a rate and a GST rate.': 'ಸಾಲು {n} ಗೆ ಪ್ರಮಾಣ, ದರ ಮತ್ತು GST ದರ ಬೇಕು.',
  'Buyer GSTIN': 'ಖರೀದಿದಾರರ GSTIN',
  'Qty': 'ಪ್ರಮಾಣ',
  'Rate': 'ದರ',
  'Reason (optional)': 'ಕಾರಣ (ಬೇಕಿದ್ದರೆ)',
  'Preview the amendment': 'ತಿದ್ದುಪಡಿ ಮೊದಲು ನೋಡಿ',
  'Debit note against {id}': '{id} ವಿರುದ್ಧ ಡೆಬಿಟ್ ನೋಟ್',
  'Credit note against {id}': '{id} ವಿರುದ್ಧ ಕ್ರೆಡಿಟ್ ನೋಟ್',
  'Adds to what {name} owes, with GST at the invoice rates. The note goes into the GSTR-1 of its own month.': '{name} ಕೊಡಬೇಕಾದ ಮೊತ್ತಕ್ಕೆ ಸೇರುತ್ತದೆ, ಇನ್‌ವಾಯ್ಸ್ ದರದ GST ಜೊತೆ. ನೋಟ್ ಅದರದೇ ತಿಂಗಳ GSTR-1 ಗೆ ಹೋಗುತ್ತದೆ.',
  'Up to {amount} including GST. Leave the amount blank to credit the whole invoice.': 'GST ಸೇರಿ {amount} ವರೆಗೆ. ಪೂರ್ತಿ ಇನ್‌ವಾಯ್ಸ್ ಕ್ರೆಡಿಟ್ ಮಾಡಲು ಮೊತ್ತ ಖಾಲಿ ಬಿಡಿ.',
  'Say why: price revised, extra charge…': 'ಕಾರಣ ಹೇಳಿ: ಬೆಲೆ ಬದಲಾಗಿದೆ, ಹೆಚ್ಚುವರಿ ಚಾರ್ಜ್…',
  'Say why: goods returned, price reduced…': 'ಕಾರಣ ಹೇಳಿ: ಮಾಲು ವಾಪಸ್, ಬೆಲೆ ಕಡಿಮೆ…',
  'Enter the amount to add, with GST.': 'ಸೇರಿಸಬೇಕಾದ ಮೊತ್ತ GST ಸಹಿತ ಹಾಕಿ.',
  'Enter the amount, or leave it blank for the whole invoice.': 'ಮೊತ್ತ ಹಾಕಿ, ಅಥವಾ ಪೂರ್ತಿ ಇನ್‌ವಾಯ್ಸ್‌ಗೆ ಖಾಲಿ ಬಿಡಿ.',
  'Amount to add, with GST': 'ಸೇರಿಸಬೇಕಾದ ಮೊತ್ತ, GST ಸಹಿತ',
  'Amount, with GST (optional)': 'ಮೊತ್ತ, GST ಸಹಿತ (ಬೇಕಿದ್ದರೆ)',
  '{name} has paid {amount}; that becomes due back to them.': '{name} ಈಗಾಗಲೇ {amount} ಕೊಟ್ಟಿದ್ದಾರೆ; ಅದು ಅವರಿಗೆ ವಾಪಸ್ ಕೊಡಬೇಕಾಗುತ್ತದೆ.',
  'A credit note for the full {amount} will be posted. You will see it before anything changes.': 'ಪೂರ್ತಿ {amount} ಗೆ ಕ್ರೆಡಿಟ್ ನೋಟ್ ಪೋಸ್ಟ್ ಆಗುತ್ತದೆ. ಏನಾದರೂ ಬದಲಾಗುವ ಮೊದಲು ನೀವು ನೋಡುತ್ತೀರಿ.',
  'Read a bill': 'ಬಿಲ್ ಓದಿ',
  'Pick a photo, PDF or text of a supplier bill. MyCA reads the supplier, number, date and lines, then previews the purchase; nothing is posted until you confirm, and every figure is yours to correct.': 'ಸಪ್ಲೈಯರ್ ಬಿಲ್‌ನ ಫೋಟೋ, PDF ಅಥವಾ ಟೆಕ್ಸ್ಟ್ ಆಯ್ಕೆಮಾಡಿ. MyCA ಸಪ್ಲೈಯರ್, ನಂಬರ್, ದಿನಾಂಕ ಮತ್ತು ಸಾಲುಗಳನ್ನು ಓದಿ ಖರೀದಿಯ ಪ್ರಿವ್ಯೂ ತೋರಿಸುತ್ತದೆ; ನೀವು ಖಚಿತಪಡಿಸುವವರೆಗೆ ಏನೂ ಪೋಸ್ಟ್ ಆಗುವುದಿಲ್ಲ, ಪ್ರತಿ ಅಂಕೆಯನ್ನೂ ನೀವು ಸರಿಪಡಿಸಬಹುದು.',
  'the file': 'ಫೈಲ್',
  'Choose a bill': 'ಬಿಲ್ ಆಯ್ಕೆಮಾಡಿ',
  'Choose another bill': 'ಬೇರೆ ಬಿಲ್ ಆಯ್ಕೆಮಾಡಿ',
