  'Read from {file}': '{file} ಇಂದ ಓದಲಾಗಿದೆ',
  'Bill {number}': 'ಬಿಲ್ {number}',
  '{qty} × {rate} at {gst}% GST': '{qty} × {rate}, {gst}% GST ಜೊತೆ',
  'Preview the purchase': 'ಖರೀದಿ ಮೊದಲು ನೋಡಿ',
  'It is a new bill': 'ಇದು ಹೊಸ ಬಿಲ್',
  'Attach to {id}': '{id} ಗೆ ಸೇರಿಸಿ',
  'Attach {file} to {id}': '{file} ಅನ್ನು {id} ಗೆ ಸೇರಿಸಿ',
  'Bill from {name} read from {file}': '{file} ಇಂದ ಓದಿದ {name} ಅವರ ಬಿಲ್',
  'This looks like bill {id} already in the books: {amount}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಬಿಲ್ {id} ತರಹ ಇದೆ: {amount}',
  'This looks like bill {id} already in the books: {amount} to {party}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಬಿಲ್ {id} ತರಹ ಇದೆ: {party} ಗೆ {amount}',
  'This looks like bill {id} already in the books: {amount} on {date}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಬಿಲ್ {id} ತರಹ ಇದೆ: {date} ರಂದು {amount}',
  'This looks like bill {id} already in the books: {amount} to {party} on {date}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಬಿಲ್ {id} ತರಹ ಇದೆ: {date} ರಂದು {party} ಗೆ {amount}',
  'This looks like expense {id} already in the books: {amount}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಖರ್ಚು {id} ತರಹ ಇದೆ: {amount}',
  'This looks like expense {id} already in the books: {amount} to {party}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಖರ್ಚು {id} ತರಹ ಇದೆ: {party} ಗೆ {amount}',
  'This looks like expense {id} already in the books: {amount} on {date}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಖರ್ಚು {id} ತರಹ ಇದೆ: {date} ರಂದು {amount}',
  'This looks like expense {id} already in the books: {amount} to {party} on {date}': 'ಇದು ಈಗಾಗಲೇ ಲೆಕ್ಕದಲ್ಲಿರುವ ಖರ್ಚು {id} ತರಹ ಇದೆ: {date} ರಂದು {party} ಗೆ {amount}',
  'Reading bills needs the model switched on by whoever runs your MyCA. Until then, add the bill by hand from Purchases.': 'ಬಿಲ್ ಓದಲು ನಿಮ್ಮ MyCA ನಡೆಸುವವರು ಮಾಡೆಲ್ ಆನ್ ಮಾಡಬೇಕು. ಅಲ್ಲಿಯವರೆಗೆ ಖರೀದಿ ವಿಭಾಗದಿಂದ ಬಿಲ್ ಕೈಯಿಂದ ಸೇರಿಸಿ.',
  'The bill could not be read. Add it by hand from Purchases.': 'ಬಿಲ್ ಓದಲು ಆಗಲಿಲ್ಲ. ಖರೀದಿ ವಿಭಾಗದಿಂದ ಕೈಯಿಂದ ಸೇರಿಸಿ.',
  'Give the GST rate only if the bill shows GST. Credit is taken only when the supplier GSTIN is on the bill; add it later from the Purchases chat if you need it.': 'ಬಿಲ್‌ನಲ್ಲಿ GST ಇದ್ದರೆ ಮಾತ್ರ GST ದರ ಕೊಡಿ. ಬಿಲ್‌ನಲ್ಲಿ ಸಪ್ಲೈಯರ್ GSTIN ಇದ್ದರೆ ಮಾತ್ರ ಕ್ರೆಡಿಟ್ ಸಿಗುತ್ತದೆ; ಬೇಕಿದ್ದರೆ ನಂತರ ಖರೀದಿ ಚಾಟ್‌ನಿಂದ ಸೇರಿಸಿ.',
  'The {tax} rate must be a number, or leave it blank.': '{tax} ದರ ಅಂಕೆಯಲ್ಲಿರಬೇಕು, ಅಥವಾ ಖಾಲಿ ಬಿಡಿ.',
  '{what}: {amount} from bank, {tax} {rate}% inside': '{what}: ಬ್ಯಾಂಕ್‌ನಿಂದ {amount}, {tax} {rate}% ಸೇರಿದೆ',
  '{what}: {amount} from cash, {tax} {rate}% inside': '{what}: ನಗದು {amount}, {tax} {rate}% ಸೇರಿದೆ',
