  'Enter the {tax} rate as a number, or leave it blank.': '{tax} ದರವನ್ನು ಅಂಕೆಯಲ್ಲಿ ಹಾಕಿ, ಅಥವಾ ಖಾಲಿ ಬಿಡಿ.',
  'Including any {tax}': '{tax} ಇದ್ದರೆ ಅದನ್ನೂ ಸೇರಿಸಿ',
  '{tax} rate inside the amount (optional)': 'ಮೊತ್ತದಲ್ಲಿ ಸೇರಿರುವ {tax} ದರ (ಬೇಕಿದ್ದರೆ)',
