  '1 bill in 2B is not in your books.': '2B ಯ 1 ಬಿಲ್ ನಿಮ್ಮ ಲೆಕ್ಕದಲ್ಲಿ ಇಲ್ಲ.',
  '{n} bills in 2B are not in your books.': '2B ಯ {n} ಬಿಲ್‌ಗಳು ನಿಮ್ಮ ಲೆಕ್ಕದಲ್ಲಿ ಇಲ್ಲ.',
