  'Not added.': 'ಸೇರಿಸಲಿಲ್ಲ.',
  'Before GST: {amount}': 'GST ಗೆ ಮೊದಲು: {amount}',
  'New item {code}': 'ಹೊಸ ಐಟಂ {code}',
  'Could not load bill {id} to print. Try again.': 'ಪ್ರಿಂಟ್‌ಗಾಗಿ ಬಿಲ್ {id} ತೆರೆಯಲು ಆಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
