  'Allow Nearby devices for MyCA in Android settings, then print again.': 'Android ಸೆಟ್ಟಿಂಗ್‌ನಲ್ಲಿ MyCA ಗೆ Nearby devices ಅನುಮತಿ ಕೊಡಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಿಂಟ್ ಮಾಡಿ.',
  'Turn on Bluetooth, then print again.': 'Bluetooth ಆನ್ ಮಾಡಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಿಂಟ್ ಮಾಡಿ.',
