  'Torch': 'ಟಾರ್ಚ್',
  'Point the camera at the barcode on the pack.': 'ಕ್ಯಾಮೆರಾವನ್ನು ಪ್ಯಾಕೆಟ್ ಮೇಲಿನ ಬಾರ್‌ಕೋಡ್ ಕಡೆ ಹಿಡಿಯಿರಿ.',
  'IFSC (optional)': 'IFSC (ಬೇಕಿದ್ದರೆ)',
  'The record of entries fails its integrity check. Ask your CA before recording more.': 'ಎಂಟ್ರಿಗಳ ದಾಖಲೆ ಸಮಗ್ರತೆ ಪರಿಶೀಲನೆಯಲ್ಲಿ ವಿಫಲವಾಗಿದೆ. ಇನ್ನಷ್ಟು ಬರೆಯುವ ಮೊದಲು ನಿಮ್ಮ CA ಯನ್ನು ಕೇಳಿ.',
  'Liabilities': 'ಹೊಣೆಗಾರಿಕೆಗಳು',
  'It does not balance. Ask your CA to look at the books.': 'ಇದು ಬ್ಯಾಲೆನ್ಸ್ ಆಗುತ್ತಿಲ್ಲ. ಲೆಕ್ಕ ನೋಡಲು ನಿಮ್ಮ CA ಗೆ ಹೇಳಿ.',
  'The movements do not add up to the closing balance. Ask your CA to look.': 'ಚಲನೆಗಳು ಕೊನೆಯ ಬ್ಯಾಲೆನ್ಸ್‌ಗೆ ಹೊಂದುತ್ತಿಲ್ಲ. ನೋಡಲು ನಿಮ್ಮ CA ಗೆ ಹೇಳಿ.',
