  'Ask your CA': 'ನಿಮ್ಮ CA ಯನ್ನು ಕೇಳಿ',
  'Waiting for your CA': 'ನಿಮ್ಮ CA ಗಾಗಿ ಕಾಯುತ್ತಿದೆ',
  'No open questions. Use "Ask my CA" on an invoice, a flagged item or a month\'s review; MyCA attaches the details.': 'ಯಾವ ಪ್ರಶ್ನೆಯೂ ಬಾಕಿ ಇಲ್ಲ. ಇನ್‌ವಾಯ್ಸ್, ಗುರುತಿಸಿದ ಐಟಂ ಅಥವಾ ತಿಂಗಳ ಪರಿಶೀಲನೆಯಲ್ಲಿ "ನನ್ನ CA ಯನ್ನು ಕೇಳಿ" ಬಳಸಿ; MyCA ವಿವರ ಸೇರಿಸುತ್ತದೆ.',
  'Your CA sees these in MyCA once you have invited them from People.': 'ಜನರು ವಿಭಾಗದಿಂದ ನೀವು ಆಹ್ವಾನಿಸಿದ ನಂತರ ನಿಮ್ಮ CA ಇವುಗಳನ್ನು MyCA ನಲ್ಲಿ ನೋಡುತ್ತಾರೆ.',
  'Copied. Paste it into WhatsApp or email if your CA is not on MyCA yet.': 'ಕಾಪಿ ಆಯಿತು. ನಿಮ್ಮ CA ಇನ್ನೂ MyCA ನಲ್ಲಿ ಇಲ್ಲದಿದ್ದರೆ WhatsApp ಅಥವಾ ಇಮೇಲ್‌ನಲ್ಲಿ ಪೇಸ್ಟ್ ಮಾಡಿ.',
  'Ask about your GST, deadlines or invoices. Nothing is posted to your books until you confirm it. MyCA works from the rules it shows you; it is not a chartered accountant and does not give tax or legal advice.': 'ನಿಮ್ಮ GST, ಗಡುವು ಅಥವಾ ಇನ್‌ವಾಯ್ಸ್ ಬಗ್ಗೆ ಕೇಳಿ. ನೀವು ಖಚಿತಪಡಿಸುವವರೆಗೆ ನಿಮ್ಮ ಲೆಕ್ಕಕ್ಕೆ ಏನೂ ಪೋಸ್ಟ್ ಆಗುವುದಿಲ್ಲ. MyCA ತಾನು ತೋರಿಸುವ ನಿಯಮಗಳ ಪ್ರಕಾರ ಕೆಲಸ ಮಾಡುತ್ತದೆ; ಇದು ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ ಅಲ್ಲ, ತೆರಿಗೆ ಅಥವಾ ಕಾನೂನು ಸಲಹೆ ಕೊಡುವುದಿಲ್ಲ.',
  'Report this answer': 'ಈ ಉತ್ತರದ ಬಗ್ಗೆ ದೂರು ಕೊಡಿ',
  'Tell us what is wrong. The answer is sent to MyCA for review, without your books.': 'ಏನು ತಪ್ಪು ಎಂದು ಹೇಳಿ. ಉತ್ತರವನ್ನು ಪರಿಶೀಲನೆಗಾಗಿ MyCA ಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ನಿಮ್ಮ ಲೆಕ್ಕ ಇಲ್ಲದೆ.',
  'Wrong or misleading': 'ತಪ್ಪು ಅಥವಾ ದಾರಿ ತಪ್ಪಿಸುವಂಥದ್ದು',
  'Harmful or offensive': 'ಹಾನಿಕರ ಅಥವಾ ಅವಮಾನಕರ',
  'Something else': 'ಬೇರೆ ಏನೋ',
