  'Could not send the report. Try again when you are online.': 'ದೂರು ಕಳುಹಿಸಲು ಆಗಲಿಲ್ಲ. ಆನ್‌ಲೈನ್ ಆದಾಗ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
