  'At cost, with IGST under the sending registration and credit under the receiving one; the two are settled by contra.': 'ವೆಚ್ಚದಲ್ಲಿ, ಕಳುಹಿಸುವ ರಿಜಿಸ್ಟ್ರೇಶನ್‌ನಲ್ಲಿ IGST ಮತ್ತು ಪಡೆಯುವ ರಿಜಿಸ್ಟ್ರೇಶನ್‌ನಲ್ಲಿ ಕ್ರೆಡಿಟ್; ಎರಡೂ ಕಾಂಟ್ರಾ ಮೂಲಕ ಚುಕ್ತಾ ಆಗುತ್ತವೆ.',
