  'A made-up trader with three months of invoices, purchases and expenses. It cannot reach the GST portal, banks or other people, and you can delete it any time.': 'ಮೂರು ತಿಂಗಳ ಇನ್‌ವಾಯ್ಸ್, ಖರೀದಿ ಮತ್ತು ಖರ್ಚು ಇರುವ ಒಂದು ಕಾಲ್ಪನಿಕ ವ್ಯಾಪಾರಿ. ಇದು GST ಪೋರ್ಟಲ್, ಬ್ಯಾಂಕ್ ಅಥವಾ ಬೇರೆಯವರನ್ನು ತಲುಪುವುದಿಲ್ಲ, ಯಾವಾಗ ಬೇಕಾದರೂ ಅಳಿಸಬಹುದು.',
