  'Plan and billing': 'ಪ್ಲಾನ್ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್',
  'Your plan, trial and what it includes': 'ನಿಮ್ಮ ಪ್ಲಾನ್, ಟ್ರಯಲ್ ಮತ್ತು ಅದರಲ್ಲಿ ಏನೇನು ಸಿಗುತ್ತದೆ',
  'Connections to banks and apps': 'ಬ್ಯಾಂಕ್ ಮತ್ತು ಆ್ಯಪ್‌ಗಳ ಕನೆಕ್ಷನ್',
  'Amazon, Shopify, Razorpay and Zoho': 'Amazon, Shopify, Razorpay ಮತ್ತು Zoho',
  'Only what went wrong in the app. Names, amounts, GSTINs and phone numbers are removed before it leaves the phone.': 'ಆ್ಯಪ್‌ನಲ್ಲಿ ಏನು ತಪ್ಪಾಯಿತು ಎಂಬುದು ಮಾತ್ರ. ಫೋನ್ ಬಿಡುವ ಮೊದಲು ಹೆಸರು, ಮೊತ್ತ, GSTIN ಮತ್ತು ಫೋನ್ ನಂಬರ್ ತೆಗೆಯಲಾಗುತ್ತದೆ.',
  'Its books, documents and members go with it. Backups are kept for fourteen days, after which it cannot be recovered.': 'ಅದರ ಲೆಕ್ಕ, ದಾಖಲೆಗಳು ಮತ್ತು ಸದಸ್ಯರು ಕೂಡ ಹೋಗುತ್ತಾರೆ. ಬ್ಯಾಕಪ್ ಹದಿನಾಲ್ಕು ದಿನ ಇಡಲಾಗುತ್ತದೆ, ನಂತರ ಮತ್ತೆ ಪಡೆಯಲು ಆಗುವುದಿಲ್ಲ.',
  'Privacy notice, terms, Grievance Officer, and requests to see, correct or erase your data': 'ಪ್ರೈವಸಿ ನೋಟಿಸ್, ಷರತ್ತುಗಳು, ಕುಂದುಕೊರತೆ ಅಧಿಕಾರಿ, ಮತ್ತು ನಿಮ್ಮ ಡೇಟಾ ನೋಡಲು, ಸರಿಪಡಿಸಲು ಅಥವಾ ಅಳಿಸಲು ಕೋರಿಕೆ',
  'Google Play is processing the payment. The plan starts as soon as it clears.': 'Google Play ಪಾವತಿ ಪ್ರೊಸೆಸ್ ಮಾಡುತ್ತಿದೆ. ಪಾವತಿ ಆದ ತಕ್ಷಣ ಪ್ಲಾನ್ ಶುರುವಾಗುತ್ತದೆ.',
  'Google Play did not complete the payment. Nothing was charged.': 'Google Play ಪಾವತಿ ಪೂರ್ತಿ ಮಾಡಲಿಲ್ಲ. ಯಾವ ಹಣವೂ ಕಡಿತವಾಗಿಲ್ಲ.',
  'Thank you. The plan is on for this business.': 'ಧನ್ಯವಾದ. ಈ ವ್ಯಾಪಾರಕ್ಕೆ ಪ್ಲಾನ್ ಚಾಲೂ ಆಗಿದೆ.',
  'Thank you. {plan} is on for this business.': 'ಧನ್ಯವಾದ. ಈ ವ್ಯಾಪಾರಕ್ಕೆ {plan} ಚಾಲೂ ಆಗಿದೆ.',
  'The payment went through but MyCA could not confirm it yet. It will be picked up automatically.': 'ಪಾವತಿ ಆಗಿದೆ, ಆದರೆ MyCA ಇನ್ನೂ ಖಚಿತಪಡಿಸಿಲ್ಲ. ಅದು ತಾನಾಗಿ ಆಗುತ್ತದೆ.',
  'Google Play could not open the payment. Check that you are signed in to the Play Store and try again.': 'Google Play ಪಾವತಿ ತೆರೆಯಲು ಆಗಲಿಲ್ಲ. Play Store ನಲ್ಲಿ ಸೈನ್ ಇನ್ ಆಗಿದ್ದೀರಾ ನೋಡಿ, ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  'This is a Google Play test purchase: no real money is taken.': 'ಇದು Google Play ಟೆಸ್ಟ್ ಖರೀದಿ: ನಿಜವಾದ ಹಣ ಕಡಿತವಾಗುವುದಿಲ್ಲ.',
  '{plan} (current)': '{plan} (ಈಗಿನದು)',
  'Opening soon. It opens once the professional who reviews and files is named here.': 'ಶೀಘ್ರದಲ್ಲೇ ಶುರು. ಪರಿಶೀಲಿಸಿ ಫೈಲ್ ಮಾಡುವ ವೃತ್ತಿಪರರ ಹೆಸರು ಇಲ್ಲಿ ಬಂದ ನಂತರ ತೆರೆಯುತ್ತದೆ.',
  'Your reviewing professional: {name}': 'ನಿಮ್ಮ ಪರಿಶೀಲನಾ ವೃತ್ತಿಪರರು: {name}',
  'Subscribe to {plan}': '{plan} ಗೆ ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಮಾಡಿ',
  'Manage or cancel in Google Play': 'Google Play ನಲ್ಲಿ ಬದಲಿಸಿ ಅಥವಾ ರದ್ದುಮಾಡಿ',
  'To switch plans, cancel in Google Play and subscribe to the other plan when this one ends.': 'ಪ್ಲಾನ್ ಬದಲಿಸಲು, Google Play ನಲ್ಲಿ ರದ್ದುಮಾಡಿ, ಇದು ಮುಗಿದಾಗ ಬೇರೆ ಪ್ಲಾನ್‌ಗೆ ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಮಾಡಿ.',
  'Only the owner can change the plan.': 'ಪ್ಲಾನ್ ಅನ್ನು ಮಾಲೀಕರು ಮಾತ್ರ ಬದಲಿಸಬಹುದು.',
  'MyCA is software. It is not a firm of chartered accountants and does not give tax or legal advice. You approve every return before it is filed.': 'MyCA ಒಂದು ಸಾಫ್ಟ್‌ವೇರ್. ಇದು ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ ಸಂಸ್ಥೆ ಅಲ್ಲ, ತೆರಿಗೆ ಅಥವಾ ಕಾನೂನು ಸಲಹೆ ಕೊಡುವುದಿಲ್ಲ. ಪ್ರತಿ ರಿಟರ್ನ್ ಫೈಲ್ ಆಗುವ ಮೊದಲು ನೀವು ಅನುಮೋದಿಸುತ್ತೀರಿ.',
  'Plans are bought from Google Play in the MyCA Android app. A plan bought there works here too.': 'ಪ್ಲಾನ್‌ಗಳನ್ನು MyCA Android ಆ್ಯಪ್‌ನಲ್ಲಿ Google Play ಇಂದ ಕೊಳ್ಳಲಾಗುತ್ತದೆ. ಅಲ್ಲಿ ಕೊಂಡ ಪ್ಲಾನ್ ಇಲ್ಲೂ ಕೆಲಸ ಮಾಡುತ್ತದೆ.',
  'See and export your books': 'ನಿಮ್ಮ ಲೆಕ್ಕ ನೋಡಿ ಮತ್ತು ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಮಾಡಿ',
  'Unlimited invoices, bills, receipts and payments': 'ಎಷ್ಟು ಬೇಕಾದರೂ ಇನ್‌ವಾಯ್ಸ್, ಬಿಲ್, ರಸೀದಿ ಮತ್ತು ಪಾವತಿ',
  'GSTR-1 and GSTR-3B worked out from your books': 'ನಿಮ್ಮ ಲೆಕ್ಕದಿಂದ GSTR-1 ಮತ್ತು GSTR-3B ಸಿದ್ಧ',
  'File GSTR-1 and GSTR-3B on the GST portal, with your CA\'s approval': 'ನಿಮ್ಮ CA ಅನುಮೋದನೆಯೊಂದಿಗೆ GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ GSTR-1 ಮತ್ತು GSTR-3B ಫೈಲ್ ಮಾಡಿ',
  'Ask MyCA in plain words': 'MyCA ಯನ್ನು ಸರಳ ಮಾತಿನಲ್ಲಿ ಕೇಳಿ',
  'E-invoices (IRN) and GSTIN checks': 'ಇ-ಇನ್‌ವಾಯ್ಸ್ (IRN) ಮತ್ತು GSTIN ಪರಿಶೀಲನೆ',
  'Amazon, Shopify, Razorpay, Zoho and bank connections': 'Amazon, Shopify, Razorpay, Zoho ಮತ್ತು ಬ್ಯಾಂಕ್ ಕನೆಕ್ಷನ್',
  'Ask and post on WhatsApp': 'WhatsApp ನಲ್ಲಿ ಕೇಳಿ ಮತ್ತು ಎಂಟ್ರಿ ಮಾಡಿ',
  'Staff and your accountant in the same books': 'ಸಿಬ್ಬಂದಿ ಮತ್ತು ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಒಂದೇ ಲೆಕ್ಕದಲ್ಲಿ',
  'An independent GST practitioner or chartered accountant, named before you subscribe, reviews and files your GST and TDS returns every month. That professional, not MyCA, is responsible for their work': 'ನೀವು ಸಬ್‌ಸ್ಕ್ರೈಬ್ ಮಾಡುವ ಮೊದಲೇ ಹೆಸರಿಸಲಾದ ಸ್ವತಂತ್ರ GST ಪ್ರಾಕ್ಟೀಷನರ್ ಅಥವಾ ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ ಪ್ರತಿ ತಿಂಗಳು ನಿಮ್ಮ GST ಮತ್ತು TDS ರಿಟರ್ನ್ ಪರಿಶೀಲಿಸಿ ಫೈಲ್ ಮಾಡುತ್ತಾರೆ. ಅವರ ಕೆಲಸಕ್ಕೆ ಆ ವೃತ್ತಿಪರರೇ ಜವಾಬ್ದಾರರು, MyCA ಅಲ್ಲ',
  'Correction promise: if a return filed through MyCA is wrong because of an error in MyCA, we prepare the correction at no charge. Interest, late fees and penalties are not covered': 'ತಿದ್ದುಪಡಿ ಭರವಸೆ: MyCA ದೋಷದಿಂದ MyCA ಮೂಲಕ ಫೈಲ್ ಆದ ರಿಟರ್ನ್ ತಪ್ಪಾದರೆ, ನಾವು ಉಚಿತವಾಗಿ ತಿದ್ದುಪಡಿ ಸಿದ್ಧಪಡಿಸುತ್ತೇವೆ. ಬಡ್ಡಿ, ಲೇಟ್ ಫೀ ಮತ್ತು ದಂಡ ಇದರಲ್ಲಿ ಸೇರಿಲ್ಲ',
  'Priority support': 'ಮೊದಲ ಆದ್ಯತೆಯ ಸಹಾಯ',
  'Unlimited invoices, any number of people': 'ಎಷ್ಟು ಬೇಕಾದರೂ ಇನ್‌ವಾಯ್ಸ್, ಎಷ್ಟು ಜನ ಬೇಕಾದರೂ',
  'Unlimited invoices, just you': 'ಎಷ್ಟು ಬೇಕಾದರೂ ಇನ್‌ವಾಯ್ಸ್, ನೀವು ಮಾತ್ರ',
  'Unlimited invoices, up to {people} people': 'ಎಷ್ಟು ಬೇಕಾದರೂ ಇನ್‌ವಾಯ್ಸ್, {people} ಜನರವರೆಗೆ',
  '{invoices} invoices a month, any number of people': 'ತಿಂಗಳಿಗೆ {invoices} ಇನ್‌ವಾಯ್ಸ್, ಎಷ್ಟು ಜನ ಬೇಕಾದರೂ',
  '{invoices} invoices a month, just you': 'ತಿಂಗಳಿಗೆ {invoices} ಇನ್‌ವಾಯ್ಸ್, ನೀವು ಮಾತ್ರ',
  '{invoices} invoices a month, up to {people} people': 'ತಿಂಗಳಿಗೆ {invoices} ಇನ್‌ವಾಯ್ಸ್, {people} ಜನರವರೆಗೆ',
  '{price} a month on Google Play, GST included': 'Google Play ನಲ್ಲಿ ತಿಂಗಳಿಗೆ {price}, GST ಸೇರಿ',
  '{price} a month plus GST': 'ತಿಂಗಳಿಗೆ {price} ಜೊತೆಗೆ GST',
  'Renews every month at {price} until you cancel. Cancel any time in Google Play, Subscriptions; the plan runs to the end of the month you paid for. Google Play handles refunds.': 'ನೀವು ರದ್ದುಮಾಡುವವರೆಗೆ ಪ್ರತಿ ತಿಂಗಳು {price} ಗೆ ರಿನ್ಯೂ ಆಗುತ್ತದೆ. Google Play, Subscriptions ನಲ್ಲಿ ಯಾವಾಗ ಬೇಕಾದರೂ ರದ್ದುಮಾಡಿ; ನೀವು ಪಾವತಿಸಿದ ತಿಂಗಳ ಕೊನೆಯವರೆಗೆ ಪ್ಲಾನ್ ನಡೆಯುತ್ತದೆ. ರೀಫಂಡ್ Google Play ನೋಡಿಕೊಳ್ಳುತ್ತದೆ.',
  'Renews every month at {price} plus GST until you cancel. Cancel any time in Google Play, Subscriptions; the plan runs to the end of the month you paid for. Google Play handles refunds.': 'ನೀವು ರದ್ದುಮಾಡುವವರೆಗೆ ಪ್ರತಿ ತಿಂಗಳು {price} ಜೊತೆಗೆ GST ಗೆ ರಿನ್ಯೂ ಆಗುತ್ತದೆ. Google Play, Subscriptions ನಲ್ಲಿ ಯಾವಾಗ ಬೇಕಾದರೂ ರದ್ದುಮಾಡಿ; ನೀವು ಪಾವತಿಸಿದ ತಿಂಗಳ ಕೊನೆಯವರೆಗೆ ಪ್ಲಾನ್ ನಡೆಯುತ್ತದೆ. ರೀಫಂಡ್ Google Play ನೋಡಿಕೊಳ್ಳುತ್ತದೆ.',
  'Free trial of {plan}: 1 day left.': '{plan} ಉಚಿತ ಟ್ರಯಲ್: 1 ದಿನ ಉಳಿದಿದೆ.',
  'Free trial of {plan}: {n} days left.': '{plan} ಉಚಿತ ಟ್ರಯಲ್: {n} ದಿನ ಉಳಿದಿವೆ.',
  'Google Play is still processing the payment. The plan starts as soon as it clears.': 'Google Play ಇನ್ನೂ ಪಾವತಿ ಪ್ರೊಸೆಸ್ ಮಾಡುತ್ತಿದೆ. ಪಾವತಿ ಆದ ತಕ್ಷಣ ಪ್ಲಾನ್ ಶುರುವಾಗುತ್ತದೆ.',
  'Google Play could not take the last payment, so the books are read-only. Fix the payment method in Google Play to get the plan back.': 'Google Play ಕೊನೆಯ ಪಾವತಿ ತೆಗೆದುಕೊಳ್ಳಲು ಆಗಲಿಲ್ಲ, ಹಾಗಾಗಿ ಲೆಕ್ಕ ನೋಡಲು ಮಾತ್ರ. ಪ್ಲಾನ್ ಮತ್ತೆ ಪಡೆಯಲು Google Play ನಲ್ಲಿ ಪಾವತಿ ವಿಧಾನ ಸರಿಪಡಿಸಿ.',
  'The free trial has ended, so the books are read-only: you can still see, ask and export. Choose a plan to post again.': 'ಉಚಿತ ಟ್ರಯಲ್ ಮುಗಿದಿದೆ, ಹಾಗಾಗಿ ಲೆಕ್ಕ ನೋಡಲು ಮಾತ್ರ: ನೀವು ಈಗಲೂ ನೋಡಬಹುದು, ಕೇಳಬಹುದು ಮತ್ತು ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಮಾಡಬಹುದು. ಮತ್ತೆ ಪೋಸ್ಟ್ ಮಾಡಲು ಪ್ಲಾನ್ ಆಯ್ಕೆಮಾಡಿ.',
  'You are on {plan}. It will not renew.': 'ನೀವು {plan} ನಲ್ಲಿದ್ದೀರಿ. ಇದು ರಿನ್ಯೂ ಆಗುವುದಿಲ್ಲ.',
  'You are on {plan} until {date}. It will not renew.': 'ನೀವು {date} ವರೆಗೆ {plan} ನಲ್ಲಿದ್ದೀರಿ. ಇದು ರಿನ್ಯೂ ಆಗುವುದಿಲ್ಲ.',
  'You are on {plan}.': 'ನೀವು {plan} ನಲ್ಲಿದ್ದೀರಿ.',
  'You are on {plan}, renews {date}.': 'ನೀವು {plan} ನಲ್ಲಿದ್ದೀರಿ, {date} ರಂದು ರಿನ್ಯೂ ಆಗುತ್ತದೆ.',
  'Off unless you tick it. Only what went wrong in the app, with names, amounts, GSTINs and phone numbers removed. You can change this later under Your business.': 'ನೀವು ಟಿಕ್ ಮಾಡದಿದ್ದರೆ ಆಫ್ ಇರುತ್ತದೆ. ಆ್ಯಪ್‌ನಲ್ಲಿ ಏನು ತಪ್ಪಾಯಿತು ಎಂಬುದು ಮಾತ್ರ, ಹೆಸರು, ಮೊತ್ತ, GSTIN ಮತ್ತು ಫೋನ್ ನಂಬರ್ ತೆಗೆದು. ನಂತರ ನಿಮ್ಮ ವ್ಯಾಪಾರ ವಿಭಾಗದಲ್ಲಿ ಇದನ್ನು ಬದಲಿಸಬಹುದು.',
  'See what MyCA holds about me': 'MyCA ಬಳಿ ನನ್ನ ಬಗ್ಗೆ ಏನಿದೆ ನೋಡಿ',
  'A summary of your personal data and who it was shared with': 'ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಡೇಟಾದ ಸಾರಾಂಶ ಮತ್ತು ಅದನ್ನು ಯಾರ ಜೊತೆ ಹಂಚಲಾಗಿದೆ',
  'Correct or complete my information': 'ನನ್ನ ಮಾಹಿತಿ ಸರಿಪಡಿಸಿ ಅಥವಾ ಪೂರ್ತಿ ಮಾಡಿ',
  'Tell us what is wrong': 'ಏನು ತಪ್ಪು ಎಂದು ಹೇಳಿ',
  'Erase my information': 'ನನ್ನ ಮಾಹಿತಿ ಅಳಿಸಿ',
  'Something you cannot delete yourself in the app': 'ಆ್ಯಪ್‌ನಲ್ಲಿ ನೀವೇ ಅಳಿಸಲು ಆಗದ್ದು',
  'Withdraw my consent': 'ನನ್ನ ಒಪ್ಪಿಗೆ ಹಿಂಪಡೆಯಿರಿ',
  'We stop using your information; your account is closed': 'ನಾವು ನಿಮ್ಮ ಮಾಹಿತಿ ಬಳಸುವುದನ್ನು ನಿಲ್ಲಿಸುತ್ತೇವೆ; ನಿಮ್ಮ ಅಕೌಂಟ್ ಮುಚ್ಚಲಾಗುತ್ತದೆ',
  'Nominate someone to act for me': 'ನನ್ನ ಪರವಾಗಿ ಕೆಲಸ ಮಾಡಲು ಯಾರನ್ನಾದರೂ ನಾಮನಿರ್ದೇಶನ ಮಾಡಿ',
  'If you die or cannot act yourself': 'ನೀವು ತೀರಿಕೊಂಡರೆ ಅಥವಾ ನೀವೇ ಏನೂ ಮಾಡಲು ಆಗದಿದ್ದರೆ',
  'Make a complaint': 'ದೂರು ಕೊಡಿ',
  'Goes to the Grievance Officer': 'ಕುಂದುಕೊರತೆ ಅಧಿಕಾರಿಗೆ ಹೋಗುತ್ತದೆ',
  'Their name': 'ಅವರ ಹೆಸರು',
  'Their phone number or email': 'ಅವರ ಫೋನ್ ನಂಬರ್ ಅಥವಾ ಇಮೇಲ್',
  'Under the Digital Personal Data Protection Act, 2023. Every request gets a reference number and an answer within 30 days. If you are not satisfied, you can complain to the Data Protection Board of India.': 'ಡಿಜಿಟಲ್ ವೈಯಕ್ತಿಕ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಕಾಯ್ದೆ, 2023 ರ ಅಡಿ. ಪ್ರತಿ ಕೋರಿಕೆಗೆ ರೆಫರೆನ್ಸ್ ನಂಬರ್ ಮತ್ತು 30 ದಿನದೊಳಗೆ ಉತ್ತರ ಸಿಗುತ್ತದೆ. ತೃಪ್ತಿ ಇಲ್ಲದಿದ್ದರೆ, ಭಾರತದ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಮಂಡಳಿಗೆ ದೂರು ಕೊಡಬಹುದು.',
  'Tap to write to them': 'ಅವರಿಗೆ ಬರೆಯಲು ಟ್ಯಾಪ್ ಮಾಡಿ',
  'Terms of service': 'ಸೇವಾ ಷರತ್ತುಗಳು',
  'Refunds and cancellation': 'ರೀಫಂಡ್ ಮತ್ತು ರದ್ದು',
  'Grievance redressal': 'ಕುಂದುಕೊರತೆ ಪರಿಹಾರ',
  'MyCA is software by ML Dynamic Solutions Private Limited. It is not a firm of chartered accountants and does not give tax or legal advice. You approve every return before it is filed.': 'MyCA, ML Dynamic Solutions Private Limited ನ ಸಾಫ್ಟ್‌ವೇರ್. ಇದು ಚಾರ್ಟರ್ಡ್ ಅಕೌಂಟೆಂಟ್ ಸಂಸ್ಥೆ ಅಲ್ಲ, ತೆರಿಗೆ ಅಥವಾ ಕಾನೂನು ಸಲಹೆ ಕೊಡುವುದಿಲ್ಲ. ಪ್ರತಿ ರಿಟರ್ನ್ ಫೈಲ್ ಆಗುವ ಮೊದಲು ನೀವು ಅನುಮೋದಿಸುತ್ತೀರಿ.',
  'Open, answer due by {date}': 'ತೆರೆದಿದೆ, {date} ಒಳಗೆ ಉತ್ತರ',
  'Seller Central → Apps and Services → Develop apps: create a private SP-API app, note the LWA client id and secret, and authorise it to get the refresh token. Marketplace id is A21TJRUUN4KGV for India; region IN.': 'Seller Central → Apps and Services → Develop apps: ಒಂದು private SP-API app ಮಾಡಿ, LWA client id ಮತ್ತು secret ಬರೆದಿಟ್ಟುಕೊಳ್ಳಿ, refresh token ಪಡೆಯಲು ಅದನ್ನು authorise ಮಾಡಿ. ಭಾರತಕ್ಕೆ Marketplace id A21TJRUUN4KGV; region IN.',
  'Shopify admin → Settings → Apps and sales channels → Develop apps: create an app with read_orders and read_shopify_payments_payouts, install it, and copy the Admin API access token. Shop domain is the myshopify.com host.': 'Shopify admin → Settings → Apps and sales channels → Develop apps: read_orders ಮತ್ತು read_shopify_payments_payouts ಇರುವ app ಮಾಡಿ, install ಮಾಡಿ, Admin API access token ಕಾಪಿ ಮಾಡಿ. Shop domain ಎಂದರೆ myshopify.com host.',
  'Razorpay dashboard → Account & Settings → API Keys: generate the key id and secret (test or live).': 'Razorpay dashboard → Account & Settings → API Keys: key id ಮತ್ತು secret ತಯಾರಿಸಿ (test ಅಥವಾ live).',
  'Zoho API console → Self Client: create a client, generate a code for ZohoBooks.fullaccess.all, exchange it for a refresh token; org id from Zoho Books settings; dc is in for India.': 'Zoho API console → Self Client: ಒಂದು client ಮಾಡಿ, ZohoBooks.fullaccess.all ಗೆ code ತಯಾರಿಸಿ, ಅದನ್ನು refresh token ಗೆ ಬದಲಿಸಿ; org id Zoho Books settings ನಲ್ಲಿ ಸಿಗುತ್ತದೆ; ಭಾರತಕ್ಕೆ dc in.',
  'Live (real portal)': 'ಲೈವ್ (ನಿಜವಾದ ಪೋರ್ಟಲ್)',
  'Test (sandbox)': 'ಟೆಸ್ಟ್ (sandbox)',
