  'Marketplaces, payment gateways and Zoho Books. Keys stay on the MyCA server, encrypted; nothing posts to the books without you.': 'ಮಾರ್ಕೆಟ್‌ಪ್ಲೇಸ್, ಪೇಮೆಂಟ್ ಗೇಟ್‌ವೇ ಮತ್ತು Zoho Books. Keys MyCA ಸರ್ವರ್‌ನಲ್ಲಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿ ಇರುತ್ತವೆ; ನೀವು ಇಲ್ಲದೆ ಲೆಕ್ಕಕ್ಕೆ ಏನೂ ಪೋಸ್ಟ್ ಆಗುವುದಿಲ್ಲ.',
  'Pulls are switched off on the service, so Pull now runs as a dry run.': 'ಸೇವೆಯಲ್ಲಿ ತರುವುದು ಆಫ್ ಆಗಿದೆ, ಹಾಗಾಗಿ "ಈಗ ತನ್ನಿ" ಪ್ರಯೋಗವಾಗಿ ಮಾತ್ರ ನಡೆಯುತ್ತದೆ.',
