  '1 bill past the MSMED limit': '1 ಬಿಲ್ MSMED ಮಿತಿ ದಾಟಿದೆ',
  '{n} bills past the MSMED limit': '{n} ಬಿಲ್‌ಗಳು MSMED ಮಿತಿ ದಾಟಿವೆ',
  '1 MSME bill to pay inside the limit': '1 MSME ಬಿಲ್ ಮಿತಿಯೊಳಗೆ ಪಾವತಿಸಬೇಕು',
  '{n} MSME bills to pay inside the limit': '{n} MSME ಬಿಲ್‌ಗಳು ಮಿತಿಯೊಳಗೆ ಪಾವತಿಸಬೇಕು',
  '{amount} not deductible until paid · 1 MSME bill open': '{amount} ಪಾವತಿಸುವವರೆಗೆ ಖರ್ಚಾಗಿ ಕಡಿತಕ್ಕೆ ಬರುವುದಿಲ್ಲ · 1 MSME ಬಿಲ್ ಬಾಕಿ',
  '{amount} not deductible until paid · {n} MSME bills open': '{amount} ಪಾವತಿಸುವವರೆಗೆ ಖರ್ಚಾಗಿ ಕಡಿತಕ್ಕೆ ಬರುವುದಿಲ್ಲ · {n} MSME ಬಿಲ್‌ಗಳು ಬಾಕಿ',
  'Next': 'ಮುಂದೆ',
  'Show me around': 'ನನಗೆ ತೋರಿಸಿ',
  'Namaste! I\'m {name}. This is Nalanda Textiles, a sample shop. Everything here is pretend, so tap anything you like. Your own books are not touched.': 'ನಮಸ್ಕಾರ! ನಾನು {name}. ಇದು Nalanda Textiles, ಒಂದು ಮಾದರಿ ಅಂಗಡಿ. ಇಲ್ಲಿರುವುದೆಲ್ಲಾ ನಕಲಿ, ಹಾಗಾಗಿ ಏನು ಬೇಕಾದರೂ ಟ್ಯಾಪ್ ಮಾಡಿ. ನಿಮ್ಮ ಸ್ವಂತ ಲೆಕ್ಕ ಮುಟ್ಟುವುದಿಲ್ಲ.',
  'The top card is your day at a glance: GST you owe this month, and anything that needs you before a filing.': 'ಮೇಲಿನ ಕಾರ್ಡ್‌ನಲ್ಲಿ ನಿಮ್ಮ ದಿನ ಒಂದೇ ನೋಟದಲ್ಲಿ: ಈ ತಿಂಗಳು ನೀವು ಕಟ್ಟಬೇಕಾದ GST, ಮತ್ತು ಫೈಲಿಂಗ್‌ಗೆ ಮೊದಲು ನೀವು ಗಮನಿಸಬೇಕಾದ್ದು.',
  'Let\'s log a sale. Tap New entry, then I sold something, and pick {customer}.': 'ಒಂದು ಮಾರಾಟ ಬರೆಯೋಣ. "ಹೊಸ ಎಂಟ್ರಿ" ಟ್ಯಾಪ್ ಮಾಡಿ, ನಂತರ "ನಾನು ಏನೋ ಮಾರಿದೆ", ಮತ್ತು {customer} ಆಯ್ಕೆಮಾಡಿ.',
  'Type an amount, say 8000, choose 18% GST, then tap Preview. MyCA works out the tax.': 'ಒಂದು ಮೊತ್ತ ಟೈಪ್ ಮಾಡಿ, ಉದಾ 8000, 18% GST ಆಯ್ಕೆಮಾಡಿ, ನಂತರ "ಪ್ರಿವ್ಯೂ" ಟ್ಯಾಪ್ ಮಾಡಿ. ತೆರಿಗೆಯನ್ನು MyCA ಲೆಕ್ಕ ಹಾಕುತ್ತದೆ.',
  'This is only a preview. Nothing reaches your books until you tap Post it.': 'ಇದು ಪ್ರಿವ್ಯೂ ಮಾತ್ರ. ನೀವು "ಪೋಸ್ಟ್ ಮಾಡಿ" ಟ್ಯಾಪ್ ಮಾಡುವವರೆಗೆ ಲೆಕ್ಕಕ್ಕೆ ಏನೂ ಹೋಗುವುದಿಲ್ಲ.',
  'Posted! The invoice is in the customer\'s thread, and GST is already counted for this month.': 'ಪೋಸ್ಟ್ ಆಯಿತು! ಇನ್‌ವಾಯ್ಸ್ ಗ್ರಾಹಕರ ಥ್ರೆಡ್‌ನಲ್ಲಿದೆ, ಮತ್ತು ಈ ತಿಂಗಳ GST ಗೆ ಈಗಾಗಲೇ ಸೇರಿದೆ.',
  'Here is what you owe. Tax on sales, less credit on purchases, and the due date for each filing.': 'ನೀವು ಎಷ್ಟು ಕಟ್ಟಬೇಕು ಇಲ್ಲಿದೆ. ಮಾರಾಟದ ಮೇಲಿನ ತೆರಿಗೆ, ಖರೀದಿಯ ಕ್ರೆಡಿಟ್ ಕಳೆದು, ಮತ್ತು ಪ್ರತಿ ಫೈಲಿಂಗ್‌ನ ಕೊನೆಯ ದಿನಾಂಕ.',
  'Rent, fuel, tea for the staff: log expenses here. MyCA picks the head and tells you why.': 'ಬಾಡಿಗೆ, ಪೆಟ್ರೋಲ್, ಸಿಬ್ಬಂದಿಯ ಟೀ: ಖರ್ಚುಗಳನ್ನು ಇಲ್ಲಿ ಬರೆಯಿರಿ. MyCA ಹೆಡ್ ಆಯ್ಕೆಮಾಡಿ ಯಾಕೆ ಎಂದೂ ಹೇಳುತ್ತದೆ.',
  'When something looks off, like a bank line that matches nothing, it shows up here with the reason.': 'ಏನಾದರೂ ಸರಿಯಿಲ್ಲ ಅನಿಸಿದಾಗ, ಉದಾಹರಣೆಗೆ ಯಾವುದಕ್ಕೂ ಹೊಂದದ ಬ್ಯಾಂಕ್ ಸಾಲು, ಅದು ಕಾರಣದೊಂದಿಗೆ ಇಲ್ಲಿ ಕಾಣುತ್ತದೆ.',
  'And you can just ask, in English or Hinglish. Try "Who owes me?"': 'ಮತ್ತು ನೀವು ಸುಮ್ಮನೆ ಕೇಳಬಹುದು, ಕನ್ನಡ ಅಥವಾ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ. "ನನಗೆ ಯಾರು ಕೊಡಬೇಕು?" ಎಂದು ಕೇಳಿ ನೋಡಿ.',
  'That\'s MyCA! Ready to set up your own books? It takes about two minutes.': 'ಇದೇ MyCA! ನಿಮ್ಮ ಸ್ವಂತ ಲೆಕ್ಕ ಶುರು ಮಾಡಲು ಸಿದ್ಧವೇ? ಸುಮಾರು ಎರಡು ನಿಮಿಷ ಸಾಕು.',
