  'Know a business owner who still keeps books by hand?': 'ಇನ್ನೂ ಕೈಯಲ್ಲೇ ಲೆಕ್ಕ ಬರೆಯುವ ವ್ಯಾಪಾರಿ ಯಾರಾದರೂ ನಿಮಗೆ ಗೊತ್ತಾ?',
  'Send them your code. When they join with it, you see it here.': 'ಅವರಿಗೆ ನಿಮ್ಮ ಕೋಡ್ ಕಳುಹಿಸಿ. ಅವರು ಅದರಿಂದ ಸೇರಿದರೆ, ಇಲ್ಲಿ ನಿಮಗೆ ಕಾಣುತ್ತದೆ.',
  '{invited} joined with your code, {converted} of them on a paid plan.': 'ನಿಮ್ಮ ಕೋಡ್‌ನಿಂದ {invited} ಜನ ಸೇರಿದ್ದಾರೆ, ಅವರಲ್ಲಿ {converted} ಜನ ಪೇಯ್ಡ್ ಪ್ಲಾನ್‌ನಲ್ಲಿದ್ದಾರೆ.',
