  'It stops working at once. Anyone holding it has to sign in again.': 'ಅದು ತಕ್ಷಣ ಕೆಲಸ ನಿಲ್ಲಿಸುತ್ತದೆ. ಅದು ಯಾರ ಕೈಯಲ್ಲಿದ್ದರೂ ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಬೇಕು.',
