  'On · 1 recovery code left': 'ಆನ್ · 1 ರಿಕವರಿ ಕೋಡ್ ಉಳಿದಿದೆ',
  'On · {n} recovery codes left': 'ಆನ್ · {n} ರಿಕವರಿ ಕೋಡ್‌ಗಳು ಉಳಿದಿವೆ',
  'Off · ask for an authenticator code at every sign-in': 'ಆಫ್ · ಪ್ರತಿ ಸೈನ್ ಇನ್‌ಗೆ ಆಥೆಂಟಿಕೇಟರ್ ಕೋಡ್ ಕೇಳಲು ಆನ್ ಮಾಡಿ',
  'New recovery codes': 'ಹೊಸ ರಿಕವರಿ ಕೋಡ್‌ಗಳು',
  'Replaces the ones you have': 'ನಿಮ್ಮ ಬಳಿ ಇರುವವುಗಳ ಬದಲಿಗೆ ಬರುತ್ತವೆ',
  'Where you are signed in': 'ನೀವು ಎಲ್ಲೆಲ್ಲಿ ಸೈನ್ ಇನ್ ಆಗಿದ್ದೀರಿ',
  'This phone': 'ಈ ಫೋನ್',
  'Sign out other devices': 'ಬೇರೆ ಡಿವೈಸ್‌ಗಳಿಂದ ಸೈನ್ ಔಟ್ ಮಾಡಿ',
  'Code from your authenticator app or a recovery code': 'ಆಥೆಂಟಿಕೇಟರ್ ಆ್ಯಪ್‌ನ ಕೋಡ್ ಅಥವಾ ರಿಕವರಿ ಕೋಡ್',
  'Turn on two-step sign-in': 'ಎರಡು ಹಂತದ ಸೈನ್ ಇನ್ ಆನ್ ಮಾಡಿ',
  'No authenticator app could open this. Scan the code or copy the key instead.': 'ಯಾವ ಆಥೆಂಟಿಕೇಟರ್ ಆ್ಯಪ್‌ನಿಂದಲೂ ಇದನ್ನು ತೆರೆಯಲು ಆಗಲಿಲ್ಲ. ಬದಲಿಗೆ ಕೋಡ್ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ ಅಥವಾ ಕೀ ಕಾಪಿ ಮಾಡಿ.',
  'Type the 6-digit code the app shows.': 'ಆ್ಯಪ್‌ನಲ್ಲಿ ಕಾಣುವ 6 ಅಂಕಿಯ ಕೋಡ್ ಟೈಪ್ ಮಾಡಿ.',
  'Scan this with Google Authenticator, Authy or any authenticator app, or copy the key into it. Then type the code it shows.': 'ಇದನ್ನು Google Authenticator, Authy ಅಥವಾ ಯಾವುದೇ ಆಥೆಂಟಿಕೇಟರ್ ಆ್ಯಪ್‌ನಿಂದ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ, ಅಥವಾ ಕೀಯನ್ನು ಅದರಲ್ಲಿ ಕಾಪಿ ಮಾಡಿ. ನಂತರ ಅದು ತೋರಿಸುವ ಕೋಡ್ ಟೈಪ್ ಮಾಡಿ.',
  'QR code for your authenticator app': 'ನಿಮ್ಮ ಆಥೆಂಟಿಕೇಟರ್ ಆ್ಯಪ್‌ಗಾಗಿ QR ಕೋಡ್',
  'Copy key': 'ಕೀ ಕಾಪಿ ಮಾಡಿ',
  'Open in authenticator app': 'ಆಥೆಂಟಿಕೇಟರ್ ಆ್ಯಪ್‌ನಲ್ಲಿ ತೆರೆಯಿರಿ',
  'Code from the app': 'ಆ್ಯಪ್‌ನ ಕೋಡ್',
  'Recovery codes': 'ರಿಕವರಿ ಕೋಡ್‌ಗಳು',
  'Save these recovery codes': 'ಈ ರಿಕವರಿ ಕೋಡ್‌ಗಳನ್ನು ಜೋಪಾನವಾಗಿ ಇಟ್ಟುಕೊಳ್ಳಿ',
  'Each one signs you in once if you lose your authenticator. Keep them somewhere safe; MyCA cannot show them again.': 'ಆಥೆಂಟಿಕೇಟರ್ ಕಳೆದುಹೋದರೆ, ಒಂದೊಂದು ಕೋಡ್‌ನಿಂದ ಒಮ್ಮೆ ಸೈನ್ ಇನ್ ಮಾಡಬಹುದು. ಇವನ್ನು ಸುರಕ್ಷಿತ ಜಾಗದಲ್ಲಿ ಇಡಿ; MyCA ಇವನ್ನು ಮತ್ತೆ ತೋರಿಸುವುದಿಲ್ಲ.',
  'Copy all': 'ಎಲ್ಲಾ ಕಾಪಿ ಮಾಡಿ',
  'Sales from a POS': 'POS ನಿಂದ ಮಾರಾಟ',
  'Documents in': 'ಬಂದ ದಾಖಲೆಗಳು',
  'A billing counter or POS posts each sale straight into the books. No confirmation per sale; you see the day\'s total here.': 'ಬಿಲ್ಲಿಂಗ್ ಕೌಂಟರ್ ಅಥವಾ POS ಪ್ರತಿ ಮಾರಾಟವನ್ನು ನೇರವಾಗಿ ಲೆಕ್ಕಕ್ಕೆ ಪೋಸ್ಟ್ ಮಾಡುತ್ತದೆ. ಒಂದೊಂದು ಮಾರಾಟಕ್ಕೂ ಕನ್ಫರ್ಮೇಶನ್ ಇಲ್ಲ; ದಿನದ ಒಟ್ಟು ಇಲ್ಲಿ ಕಾಣುತ್ತದೆ.',
  'A mail inbox or scanner drops bills and statements in. Nothing posts; you get a reminder to read each one.': 'ಮೇಲ್ ಇನ್‌ಬಾಕ್ಸ್ ಅಥವಾ ಸ್ಕ್ಯಾನರ್ ಬಿಲ್ ಮತ್ತು ಸ್ಟೇಟ್‌ಮೆಂಟ್‌ಗಳನ್ನು ಇಲ್ಲಿ ಹಾಕುತ್ತದೆ. ಏನೂ ಪೋಸ್ಟ್ ಆಗುವುದಿಲ್ಲ; ಪ್ರತಿಯೊಂದನ್ನೂ ಓದಲು ನಿಮಗೆ ರಿಮೈಂಡರ್ ಬರುತ್ತದೆ.',
  'Copied {text}': '{text} ಕಾಪಿ ಆಯಿತು',
  'Turn off {label}?': '{label} ಆಫ್ ಮಾಡಬೇಕೇ?',
  'Anything it sends from now on is refused. What it already recorded stays in the books.': 'ಇನ್ನು ಮುಂದೆ ಅದು ಕಳುಹಿಸುವ ಯಾವುದನ್ನೂ ತೆಗೆದುಕೊಳ್ಳುವುದಿಲ್ಲ. ಈಗಾಗಲೇ ದಾಖಲಾದದ್ದು ಲೆಕ್ಕದಲ್ಲೇ ಇರುತ್ತದೆ.',
  'Connect something': 'ಏನಾದರೂ ಕನೆಕ್ಟ್ ಮಾಡಿ',
  'Other systems that put entries or documents into these books on their own. Each gets its own key; turn it off here any time.': 'ಈ ಲೆಕ್ಕಕ್ಕೆ ತಾವಾಗಿಯೇ ಎಂಟ್ರಿ ಅಥವಾ ದಾಖಲೆ ಹಾಕುವ ಬೇರೆ ಸಿಸ್ಟಮ್‌ಗಳು. ಪ್ರತಿಯೊಂದಕ್ಕೂ ಒಂದು ಕೀ ಇರುತ್ತದೆ; ಯಾವಾಗ ಬೇಕಾದರೂ ಇಲ್ಲಿಂದ ಆಫ್ ಮಾಡಿ.',
  'Nothing is connected yet.': 'ಇನ್ನೂ ಏನೂ ಕನೆಕ್ಟ್ ಆಗಿಲ್ಲ.',
