  'Name the system, for example "Counter till".': 'ಸಿಸ್ಟಮ್‌ಗೆ ಹೆಸರು ಕೊಡಿ, ಉದಾಹರಣೆಗೆ "ಕೌಂಟರ್ ಗಲ್ಲಾ".',
  'What is it?': 'ಇದು ಏನು?',
