  'Create key': 'ಕೀ ಮಾಡಿ',
  '{label} is connected': '{label} ಕನೆಕ್ಟ್ ಆಯಿತು',
  'Give this key to the system once. It is shown only now; if it is lost, turn this connection off and make a new one.': 'ಈ ಕೀಯನ್ನು ಸಿಸ್ಟಮ್‌ಗೆ ಒಮ್ಮೆ ಕೊಡಿ. ಇದು ಈಗ ಮಾತ್ರ ಕಾಣುತ್ತದೆ; ಕಳೆದುಹೋದರೆ, ಈ ಕನೆಕ್ಷನ್ ಆಫ್ ಮಾಡಿ ಹೊಸದು ಮಾಡಿ.',
  'Or forward bills by mail to this address; it stays on the Connections list.': 'ಅಥವಾ ಬಿಲ್‌ಗಳನ್ನು ಈ ವಿಳಾಸಕ್ಕೆ ಮೇಲ್ ಮೂಲಕ ಫಾರ್ವರ್ಡ್ ಮಾಡಿ; ಇದು ಕನೆಕ್ಷನ್‌ಗಳ ಪಟ್ಟಿಯಲ್ಲಿ ಇರುತ್ತದೆ.',
