  'That file is not a MyCA export or backup.': 'ಆ ಫೈಲ್ MyCA ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಅಥವಾ ಬ್ಯಾಕಪ್ ಅಲ್ಲ.',
  'Replace {name} with {file}?': '{name} ಬದಲಿಗೆ {file} ಹಾಕಬೇಕೇ?',
  'The books on MyCA become the ones in this file (1 invoice). What is on MyCA now is kept in the audit trail and the fourteen-day backups, but the screens will show the file.': 'MyCA ಯಲ್ಲಿನ ಲೆಕ್ಕ ಈ ಫೈಲ್‌ನಲ್ಲಿರುವುದಾಗುತ್ತದೆ (1 ಇನ್‌ವಾಯ್ಸ್). ಈಗ MyCA ಯಲ್ಲಿ ಇರುವುದು ಆಡಿಟ್ ಟ್ರೇಲ್ ಮತ್ತು ಹದಿನಾಲ್ಕು ದಿನದ ಬ್ಯಾಕಪ್‌ಗಳಲ್ಲಿ ಇರುತ್ತದೆ, ಆದರೆ ಸ್ಕ್ರೀನ್‌ಗಳಲ್ಲಿ ಫೈಲ್‌ನದ್ದೇ ಕಾಣುತ್ತದೆ.',
  'The books on MyCA become the ones in this file ({n} invoices). What is on MyCA now is kept in the audit trail and the fourteen-day backups, but the screens will show the file.': 'MyCA ಯಲ್ಲಿನ ಲೆಕ್ಕ ಈ ಫೈಲ್‌ನಲ್ಲಿರುವುದಾಗುತ್ತದೆ ({n} ಇನ್‌ವಾಯ್ಸ್‌ಗಳು). ಈಗ MyCA ಯಲ್ಲಿ ಇರುವುದು ಆಡಿಟ್ ಟ್ರೇಲ್ ಮತ್ತು ಹದಿನಾಲ್ಕು ದಿನದ ಬ್ಯಾಕಪ್‌ಗಳಲ್ಲಿ ಇರುತ್ತದೆ, ಆದರೆ ಸ್ಕ್ರೀನ್‌ಗಳಲ್ಲಿ ಫೈಲ್‌ನದ್ದೇ ಕಾಣುತ್ತದೆ.',
  'Replace': 'ಬದಲಿಸಿ',
  'Replaced from {file}: done.': '{file} ನಿಂದ ಬದಲಿಸಲಾಗಿದೆ: ಆಯಿತು.',
  'Replaced from {file}: {invoices} invoices, {documents} documents.': '{file} ನಿಂದ ಬದಲಿಸಲಾಗಿದೆ: {invoices} ಇನ್‌ವಾಯ್ಸ್‌ಗಳು, {documents} ದಾಖಲೆಗಳು.',
  'Delete your account?': 'ನಿಮ್ಮ ಅಕೌಂಟ್ ಅಳಿಸಬೇಕೇ?',
  'You are signed out everywhere. Your name, number, email and Google link are erased after 30 days; signing in again before then cancels it. A business where you are the only owner is deleted with you; one with another owner stays with them.': 'ನೀವು ಎಲ್ಲಾ ಕಡೆ ಸೈನ್ ಔಟ್ ಆಗುತ್ತೀರಿ. ನಿಮ್ಮ ಹೆಸರು, ನಂಬರ್, ಇಮೇಲ್ ಮತ್ತು Google ಲಿಂಕ್ 30 ದಿನಗಳ ನಂತರ ಅಳಿಸಲಾಗುತ್ತದೆ; ಅದಕ್ಕೂ ಮೊದಲು ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಿದರೆ ಇದು ರದ್ದಾಗುತ್ತದೆ. ನೀವೊಬ್ಬರೇ ಮಾಲೀಕರಾಗಿರುವ ವ್ಯಾಪಾರ ನಿಮ್ಮ ಜೊತೆಗೇ ಅಳಿಸಲಾಗುತ್ತದೆ; ಇನ್ನೊಬ್ಬ ಮಾಲೀಕರಿರುವ ವ್ಯಾಪಾರ ಅವರ ಬಳಿಯೇ ಇರುತ್ತದೆ.',
